/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"지반과 기초":{"묶음":[{"머리":"허용지내력","줄":[{"t":"허용지내력(지반의 허용지지력) 단위는 kN/㎡이다.","src":"기출 2025-43"},{"t":"지반 종류별 허용지내력이 큰 순서: 화성암 > 수성암 > 자갈 > 자갈과 모래의 혼합물 > 모래 섞인 점토 > 모래.","src":"기출 2021-41"},{"t":"철근콘크리트 독립기초의 기초판 크기(면적)는 지반의 허용지내력으로 정한다. 허용휨내력·허용전단내력·허용인장내력·허용부착내력은 기초판 면적을 정하는 기준이 아니다.","src":"기출 2024-49"},{"t":"기초판 소요면적 = 기초에 작용하는 하중 ÷ 지반의 허용지내력.","src":"보충"}]},{"머리":"기초의 종류","줄":[{"t":"기초판의 형식에 따른 분류: 독립기초, 연속기초(줄기초), 복합기초, 온통기초(매트기초). 잠함기초는 기초판 형식 분류에 해당하지 않는다.","src":"기출 2025-41"},{"t":"독립기초는 기둥 1개의 하중을 1개의 기초판으로 지지한다.","src":"보충"},{"t":"연속기초(줄기초)는 벽체 또는 일렬로 늘어선 기둥 밑을 연속해서 받치는 기초다.","src":"보충"},{"t":"복합기초는 2개 이상 기둥의 하중을 1개의 기초판으로 지지하는 기초다.","src":"기출 2022-42"},{"t":"온통기초(매트기초)는 건물 하부 전체를 하나의 기초판으로 받치는 기초다.","src":"보충"},{"t":"깊은기초에는 말뚝기초, 피어기초, 케이슨(잠함)기초가 있다.","src":"보충"}]},{"머리":"부등침하","줄":[{"t":"부등침하 방지: 같은 종류의 지정을 사용한다. 서로 다른 종류의 지정을 섞어 쓰면 부등침하 원인이 된다.","src":"기출 2022-42 | 보충"},{"t":"지중보(기초보)는 기초를 서로 연결해 강성을 높이므로 부등침하 억제에 효과가 있다.","src":"기출 2022-42 | 보충"},{"t":"부등침하 원인: 연약층 두께 차이, 이질지정 병용, 지하수위 변화, 인접 건물의 하중, 건물 일부의 증축.","src":"보충"}]},{"머리":"터파기(굴토) 공법","줄":[{"t":"오픈 컷 공법: 흙의 휴식각을 고려해 별도의 흙막이를 설치하지 않고 경사지게 파는 방식.","src":"기출 2023-42"},{"t":"아일랜드 컷 공법: 중앙부를 먼저 굴토해 구조체를 설치한 뒤 외주부를 굴토한다.","src":"기출 2022-42"},{"t":"트렌치 컷 공법: 외주부를 먼저 굴토해 구조체를 설치한 뒤 중앙부를 굴토한다(아일랜드 컷의 반대 순서).","src":"기출 2023-42 | 보충"},{"t":"역타(top down) 공법: 지하 구조체를 위층부터 아래로 시공하며 굴착한다. 어스앵커 공법: 흙막이 벽을 지반에 묻은 앵커로 지지한다.","src":"기출 2023-42 | 보충"}]},{"머리":"지반 개량과 배수","줄":[{"t":"웰포인트 공법은 사질지반의 지하수를 강제 배수하는 공법이다. 점토질 연약지반의 대표 개량공법이 아니다.","src":"기출 2022-42 | 보충"},{"t":"점토질 연약지반 개량: 샌드드레인, 페이퍼드레인, 프리로딩 등 압밀 촉진 공법.","src":"보충"},{"t":"사질지반 개량: 바이브로플로테이션, 다짐말뚝 등 다짐 공법.","src":"보충"}]},{"머리":"토질 용어","줄":[{"t":"액상화: 느슨하고 포화된 사질지반이 진동·지진으로 전단저항을 잃고 액체처럼 거동하는 현상.","src":"기출 2024-48 | 보충"},{"t":"사운딩: 로드 선단의 저항체를 지중에 넣어 관입·회전·인발 저항으로 토층의 성상을 탐사하는 시험.","src":"기출 2024-48"},{"t":"샌드벌킹: 모래가 적당히 젖으면 입자 사이 수막 때문에 체적이 늘어나는 현상.","src":"기출 2024-48 | 보충"},{"t":"간극수압: 흙 입자 사이 빈틈(간극) 속 물이 가하는 압력이며 모든 방향으로 작용한다.","src":"기출 2024-48 | 보충"},{"t":"압밀: 점토지반이 하중을 받아 간극수가 빠져나가며 시간에 따라 체적이 줄어드는 현상.","src":"기출 2024-48 | 보충"}]}],"함정":[{"x":"서로 다른 종류의 지정을 사용하면 부등침하를 방지할 수 있다.","o":"서로 다른 종류의 지정을 섞어 쓰면 부등침하가 생기기 쉽다. 같은 종류의 지정을 쓴다.","src":"기출 2022-42"},{"x":"지중보는 부등침하 억제에 영향을 미치지 못한다.","o":"지중보는 기초를 연결해 부등침하를 억제한다.","src":"기출 2022-42"},{"x":"2개의 기둥에서 전달되는 하중을 1개의 기초판으로 지지하는 방식의 기초를 연속기초라고 한다.","o":"복합기초라고 한다.","src":"기출 2022-42"},{"x":"웰포인트 공법은 점토질 지반의 대표적인 연약 지반 개량공법이다.","o":"웰포인트는 사질지반의 지하수를 강제 배수하는 공법이다.","src":"기출 2022-42"},{"x":"액상화는 점토지반이 진동 및 지진 등에 의해 압축저항력을 상실하여 액체와 같이 거동하는 현상이다.","o":"액상화는 느슨하고 포화된 사질지반에서 일어난다.","src":"기출 2024-48"},{"x":"샌드벌킹(sand bulking)은 사질지반의 모래에 물이 배출되어 체적이 축소되는 현상이다.","o":"샌드벌킹은 모래가 젖어 체적이 증가하는 현상이다.","src":"기출 2024-48"},{"x":"간극수압은 모래 속에 포함된 물에 의한 하향수압을 의미한다.","o":"간극수압은 흙 입자 사이 물의 압력이며 모든 방향으로 작용한다.","src":"기출 2024-48"},{"x":"압밀은 사질지반에서 외력에 의해 공기가 제거되어 체적이 증가되는 현상이다.","o":"압밀은 점토지반에서 간극수가 빠져나가며 체적이 감소하는 현상이다.","src":"기출 2024-48"}]},"하중과 구조계획":{"묶음":[{"머리":"하중의 종류와 성격","줄":[{"t":"고정하중과 활하중은 장기하중이고, 풍하중과 지진하중은 단기하중이다.","src":"기출 2021-47, 2025-42 | 보충"},{"t":"고정하중은 구조체와 마감, 기계설비 하중 등 크기와 위치가 변하지 않는 하중이다. 골조에 고정된 영구설비하중도 고정하중이다.","src":"기출 2023-41, 2025-42"},{"t":"엘리베이터 자중은 활하중이 아니라 고정하중에 포함된다.","src":"기출 2021-47 | 보충"},{"t":"활하중은 건축물을 점유·사용함으로써 생기며, 크기와 위치가 수시로 변한다.","src":"기출 2025-42"},{"t":"응력도: 외력이 작용하는 구조부재 단면에 생기는 단위면적당 힘의 크기.","src":"기출 2023-41"},{"t":"탄성: 외력으로 변형된 물체가 외력을 제거하면 본래 모양으로 돌아가는 성질. 소성: 외력을 제거해도 변형이 남는 성질.","src":"기출 2023-41 | 보충"}]},{"머리":"적설·풍·지진하중","줄":[{"t":"기본지상적설하중은 재현기간 100년에 대한 수직 최심적설깊이를 기준으로 한다.","src":"기출 2021-47, 2025-42"},{"t":"풍하중은 건축물 형태(풍력계수 등)의 영향을 받는다.","src":"기출 2021-47"},{"t":"풍하중 관련 계수: 고도분포계수, 가스트영향계수. 지진하중 산정 관련: 반응수정계수, 중요도계수, 밑면전단력.","src":"기출 2022-41"},{"t":"반응수정계수가 클수록 산정되는 지진하중은 작아진다.","src":"기출 2021-47 | 보충"},{"t":"밑면전단력은 유효건물중량에 비례한다(V = Cs·W). 골조에 고정된 영구설비하중은 유효건물중량에 포함한다.","src":"기출 2023-41, 2025-42 | 보충"}]},{"머리":"활하중","줄":[{"t":"등분포 활하중은 부재의 영향면적이 클 때 저감해서 사용할 수 있다.","src":"기출 2023-41 | 보충"},{"t":"기본등분포활하중 크기: 주거용 건축물 거실이 가장 작다(2.0 kN/㎡). 도서관 서고 7.5 kN/㎡, 판매장 상점·기계실 공조실·공동주택 공용실 5.0 kN/㎡.","src":"기출 2024-60 | 보충"}]},{"머리":"습식·건식 구조","줄":[{"t":"습식구조(물 사용): 조적조, 철근콘크리트 라멘구조, 일체식구조, 플랫슬래브.","src":"기출 2023-47, 2024-55"},{"t":"건식구조(물 사용 안 함): 철골구조, 목구조, 트러스, 현수구조, 막구조.","src":"기출 2023-47, 2024-55 | 보충"},{"t":"조적조는 벽돌 등을 쌓는 벽식에 적합한 습식구조다.","src":"기출 2023-47"},{"t":"트러스 부재에는 주로 축방향력(인장·압축)이 작용한다.","src":"기출 2023-47 | 보충"},{"t":"현수구조는 케이블의 인장력으로 하중을 지지하고, 막구조는 막의 인장력으로 저항한다.","src":"기출 2023-47, 2024-55"},{"t":"벽식구조는 벽체와 슬래브로 하중을 전달한다.","src":"기출 2024-55"}]},{"머리":"구조형식","줄":[{"t":"절판구조: 판을 주름지게 접어 휨에 대한 저항능력을 높인 구조.","src":"기출 2021-48"},{"t":"이중골조: 수평력의 25% 이상을 부담하는 연성모멘트골조가 전단벽 또는 가새골조와 조합된 구조.","src":"기출 2021-48 | 보충"},{"t":"골조-전단벽 구조: 전단벽과 골조가 서로 작용하며 수평력에 함께 저항한다.","src":"기출 2021-48 | 보충"},{"t":"전단벽이 캔틸레버로 나와 외곽 기둥을 스트럿·타이처럼 거동시키는 구조는 아웃리거 구조다.","src":"기출 2021-48 | 보충"},{"t":"플랫슬래브 구조: 보 없이 슬래브가 하중을 기둥으로 직접 전달하는 구조. 플랫플레이트는 보와 지판이 없다.","src":"기출 2021-48, 2023-47, 2024-55"}]}],"함정":[{"x":"고정하중과 활하중은 단기하중이다.","o":"고정하중과 활하중은 장기하중이다.","src":"기출 2021-47"},{"x":"엘리베이터의 자중은 활하중에 포함된다.","o":"엘리베이터 자중은 고정하중이다.","src":"기출 2021-47"},{"x":"풍하중은 건축물 형태에 영향을 받지 않는다.","o":"풍하중은 건축물 형태의 영향을 받는다.","src":"기출 2021-47"},{"x":"반응수정계수가 클수록 산정된 지진하중의 크기도 커진다.","o":"반응수정계수가 클수록 지진하중은 작아진다.","src":"기출 2021-47"},{"x":"이중골조 구조: 수평력의 25% 미만을 부담하는 가새골조가 전단벽이나 연성모멘트 골조와 조합되어 있는 구조","o":"수평력의 25% 이상을 부담하는 연성모멘트골조가 전단벽 또는 가새골조와 조합된 구조다.","src":"기출 2021-48"},{"x":"전단벽 구조: 전단벽이 캔틸레버 형태로 나와 외곽부의 기둥을 스트럿이나 타이처럼 거동하게 함으로써 응력 및 하중을 재분배시키는 구조","o":"아웃리거 구조의 설명이다.","src":"기출 2021-48"},{"x":"골조-전단벽 구조: 수평력을 전단벽과 골조가 각각 독립적으로 저항하는 구조","o":"전단벽과 골조가 서로 작용하며 함께 저항한다.","src":"기출 2021-48"},{"x":"플랫 슬래브 구조: 슬래브의 상부하중을 보와 슬래브로 지지하는 구조","o":"플랫슬래브는 보 없이 슬래브가 기둥으로 하중을 직접 전달한다.","src":"기출 2021-48"},{"x":"고정하중은 기계설비 하중을 포함하지 않는다.","o":"고정하중은 기계설비 하중을 포함한다.","src":"기출 2023-41"},{"x":"외력을 받아 변형한 물체가 그 외력을 제거하면 본래의 모양으로 되돌아가는 성질을 소성이라고 한다.","o":"그 성질은 탄성이다.","src":"기출 2023-41"},{"x":"등분포 활하중은 저감해서 사용하면 안된다.","o":"영향면적이 클 때 저감해서 사용할 수 있다.","src":"기출 2023-41"},{"x":"지진하중 계산을 위해 사용하는 밑면전단력은 구조물유효무게에 반비례한다.","o":"밑면전단력은 유효건물중량에 비례한다.","src":"기출 2023-41"},{"x":"트러스는 부재에 전단력이 작용하는 건식구조이다.","o":"트러스 부재에는 축방향력(인장·압축)이 작용한다.","src":"기출 2023-47"},{"x":"건식구조는 물을 사용하지 않는 구조로 일체식구조, 목구조 등이 있다.","o":"일체식구조는 습식구조다. 건식구조에는 목구조, 철골구조 등이 있다.","src":"기출 2024-55"},{"x":"건축물을 점유 사용함으로써 발생하는 하중은 고정하중이다.","o":"점유·사용으로 생기는 하중은 활하중이다.","src":"기출 2025-42"},{"x":"고정하중은 활하중에 비해 하중의 크기와 위치가 수시로 변화한다.","o":"크기와 위치가 수시로 변하는 쪽은 활하중이다.","src":"기출 2025-42"},{"x":"골조에 고정된 영구설비하중은 밑면전단력 계산에서 유효건물중량에 포함되지 않는다.","o":"유효건물중량에 포함된다.","src":"기출 2025-42"},{"x":"고정하중과 활하중은 단기하중이며, 지진하중과 풍하중은 장기하중이다.","o":"고정·활하중은 장기하중, 지진·풍하중은 단기하중이다.","src":"기출 2025-42"}]},"철근콘크리트구조":{"묶음":[{"머리":"재료 성질","줄":[{"t":"철근과 콘크리트의 선팽창계수는 거의 같다.","src":"기출 2025-45"},{"t":"부착강도는 이형철근이 원형철근보다 우수하다.","src":"기출 2025-45"},{"t":"콘크리트는 압축력에 강하고 알칼리성이다(철근 부식 방지).","src":"기출 2025-45"},{"t":"철근을 적절히 배치하면 건조수축 균열을 줄일 수 있다.","src":"기출 2025-45"},{"t":"콘크리트 탄성계수는 압축시험(응력-변형률 곡선)으로 구한다. 인장시험이 아니다.","src":"기출 2022-43 | 보충"},{"t":"SD400의 SD는 이형철근, 400은 항복강도 400 N/㎟이다. 원형철근은 SR로 표시한다.","src":"기출 2022-43, 2023-44 | 보충"},{"t":"철근과 콘크리트의 부착력에 영향을 주는 요인: 콘크리트 압축강도, 피복두께, 철근 표면 상태. 철근의 항복강도는 해당하지 않는다.","src":"기출 2023-46"}]},{"머리":"피복두께","줄":[{"t":"피복두께는 최외측 철근(기둥은 띠철근, 전단철근 있는 보는 스터럽) 외면에서 콘크리트 표면까지의 최단거리다. 주근 중심이나 주근 외면 기준이 아니다.","src":"기출 2021-54, 2023-44, 2025-45 | 보충"},{"t":"설계기준압축강도 30 MPa인 옥외공기에 직접 노출되지 않는 철근콘크리트 보의 최소 피복두께는 40 mm다.","src":"기출 2021-54"},{"t":"최소 피복두께: 수중 타설 콘크리트 100 mm, 흙에 접해 영구히 흙에 묻히는 콘크리트 80 mm.","src":"보충"},{"t":"흙에 접하거나 옥외공기에 직접 노출: D19 이상 50 mm, D16 이하 40 mm.","src":"보충"},{"t":"옥외공기·흙에 직접 접하지 않는 콘크리트: 슬래브·벽체·장선 D35 이하 20 mm, D35 초과 40 mm. 보·기둥 40 mm.","src":"보충"}]},{"머리":"철근 간격·이음·정착","줄":[{"t":"보 주근을 2단으로 배근할 때 상하 철근의 순간격은 25 mm 이상이다.","src":"기출 2024-51"},{"t":"철근 순간격은 철근 지름, 굵은골재 최대치수의 4/3배, 25 mm 중 큰 값 이상으로 한다.","src":"기출 2021-54 | 보충"},{"t":"D35 이하 철근은 인장 겹침이음을 할 수 있다. D35를 초과하는 철근은 겹침이음하지 않는다.","src":"기출 2022-45 | 보충"},{"t":"기둥 주근은 기초에 정착한다.","src":"기출 2022-45, 2025-47"},{"t":"큰 보의 주근은 기둥에 정착하고, 작은 보의 주근은 큰 보에 정착한다.","src":"기출 2022-45, 2025-47 | 보충"},{"t":"직교하는 보 밑에 기둥이 없을 때 보의 주근은 보 상호 간에 정착한다.","src":"기출 2025-47"},{"t":"지중보의 주근은 기초 또는 기둥에 정착한다.","src":"기출 2022-45, 2025-47"},{"t":"슬래브 철근은 보 또는 벽체에 정착한다.","src":"기출 2022-45, 2025-47"},{"t":"갈고리는 인장철근의 정착에 효과적이다. 압축철근에는 효과가 없다.","src":"기출 2022-45, 2024-51 | 보충"}]},{"머리":"보","줄":[{"t":"보는 휨모멘트에 대해 주근(축방향 철근)을, 전단력에 대해 스터럽(늑근)을 배근한다.","src":"기출 2024-51, 2025-44"},{"t":"스터럽은 보의 사인장균열(전단균열)을 방지하려고 설치한다.","src":"기출 2022-43, 2023-43"},{"t":"늑근(스터럽)은 중앙부보다 전단력이 큰 단부에 많이 배근한다.","src":"기출 2023-43 | 보충"},{"t":"주근은 휨균열 발생을 억제하려고 배근한다. 휨균열은 보 중앙부에서 수직에 가까운 형태로 생긴다.","src":"기출 2023-43"},{"t":"양단 고정 보의 단부 주근은 상부에 배근한다.","src":"기출 2023-43"},{"t":"보 단부의 사인장균열은 전단력에 의한 주인장응력으로 생기며, 스터럽·굽힘철근으로 보강한다.","src":"기출 2024-52 | 보충"},{"t":"단순보 중앙부에서는 하단에 휨인장응력이 생겨 수직 방향 균열이 생긴다.","src":"기출 2024-52 | 보충"},{"t":"압축철근비가 클수록 장기처짐은 감소한다.","src":"기출 2024-52 | 보충"},{"t":"복근직사각형보는 인장·압축 양측에 철근을 배근한다. T형보는 슬래브 일부가 보의 플랜지를 이룬다.","src":"기출 2024-50"}]},{"머리":"기둥·벽체","줄":[{"t":"기둥 주근은 압축력에 주로 저항한다. 띠철근은 주근의 좌굴방지와 전단보강, 띠철근·나선철근은 콘크리트의 횡방향 벌어짐을 구속한다.","src":"기출 2024-51, 2025-44"},{"t":"나선철근은 기둥의 횡구속(연성·압축내력 증가)이 목적이며 휨내력 향상이 목적이 아니다.","src":"기출 2022-43 | 보충"},{"t":"기둥 주근 최소 개수: 띠철근 기둥 4개, 나선철근 기둥 6개.","src":"기출 2023-44 | 보충"},{"t":"내력벽은 자중과 상부층의 연직하중을 지지한다. 철근 배근 간격은 벽두께의 3배 이하, 450 mm 이하다.","src":"기출 2024-50 | 보충"}]},{"머리":"슬래브·기초판","줄":[{"t":"2방향 슬래브는 단변과 장변 양 방향으로 하중이 전달된다.","src":"기출 2024-50"},{"t":"1방향 슬래브 주근은 단변방향 철근이며 휨모멘트에 저항한다. 하중도 단변방향으로 더 많이 전달된다.","src":"기출 2022-43, 2025-44"},{"t":"1방향 슬래브의 배력철근은 장변방향에 배근하며, 건조수축·온도변화에 의한 균열을 방지한다.","src":"기출 2023-44, 2024-52"},{"t":"슬래브 주근은 배력철근보다 바깥쪽(슬래브 표면에 가까운 쪽)에 배근한다.","src":"기출 2023-44, 2025-44"},{"t":"독립기초판의 주근은 휨인장응력을 받는 하단에 배근한다.","src":"기출 2024-51"}]},{"머리":"굳지 않은 콘크리트","줄":[{"t":"컨시스턴시: 물의 양에 따른 반죽의 질기.","src":"기출 2022-44"},{"t":"재료분리가 생기지 않는 범위에서 단위수량이 늘면 워커빌리티가 증가한다.","src":"기출 2022-44"},{"t":"골재의 입도·입형은 워커빌리티에 영향을 준다. 물시멘트비가 클수록 블리딩 양이 늘어난다.","src":"기출 2022-44"},{"t":"콘크리트 온도는 공기량에 영향을 준다(온도가 높을수록 공기량이 감소).","src":"기출 2022-44 | 보충"},{"t":"재료분리 원인: 모르타르 점성이 적음, 부어넣는 높이가 높음, 단위수량이 많음, 운반·다짐 때 심한 진동.","src":"기출 2021-55"},{"t":"입경이 작고 표면이 거친 구형 골재는 재료분리 원인으로 보지 않는다.","src":"기출 2021-55"}]},{"머리":"균열","줄":[{"t":"소성수축균열: 경화 전 표면에서 물의 증발속도가 블리딩 속도보다 빠를 때 생긴다.","src":"기출 2021-56 | 보충"},{"t":"침하균열: 콘크리트가 침하하다가 굵은 철근 등에 걸려 철근 위에 생긴다.","src":"기출 2021-56 | 보충"},{"t":"건조수축균열: 경화 후 수분 증발로 체적이 줄어 생긴다.","src":"기출 2021-56 | 보충"},{"t":"온도균열: 내·외부 온도차가 클수록, 단면치수가 클수록 생기기 쉽다.","src":"기출 2021-56"},{"t":"하중에 의한 균열은 설계하중 초과, 부동침하 등으로 생기며 일정한 방향성이 있다. 망상균열은 소성수축·건조수축 균열의 형태다.","src":"기출 2021-56 | 보충"}]},{"머리":"거푸집","줄":[{"t":"간격재(스페이서)는 철근과 거푸집 사이의 간격(피복두께)을 유지한다. 거푸집 상호 간 간격 유지는 격리재(세퍼레이터)의 역할이다.","src":"기출 2021-54 | 보충"},{"t":"거푸집 존치기간을 압축강도로 정할 때 기둥·보·벽 등의 측면은 5 MPa 이상이다.","src":"기출 2021-54 | 보충"},{"t":"슬래브·보 밑면은 설계기준압축강도의 2/3 이상, 또한 최소 14 MPa 이상일 때 거푸집을 해체한다.","src":"보충"}]}],"함정":[{"x":"간격재는 거푸집 상호간에 일정한 간격을 유지하기 위한 것이다.","o":"간격재는 철근과 거푸집 사이 간격(피복두께)을 유지한다. 거푸집 상호 간 간격 유지는 격리재다.","src":"기출 2021-54"},{"x":"철근 조립시 철근의 간격은 철근 지름의 1.25배 이상, 굵은골재 최대치수의 1.5배 이상, 25 mm 이상의 세 가지 값 중 최대값을 사용한다.","o":"철근 지름(1.0배), 굵은골재 최대치수의 4/3배, 25 mm 중 큰 값 이상을 쓴다.","src":"기출 2021-54"},{"x":"기둥의 철근 피복두께는 띠철근(hoop) 외면이 아닌 주철근 외면에서 콘크리트 표면 까지의 거리를 말한다.","o":"기둥의 피복두께는 띠철근 외면에서 콘크리트 표면까지다.","src":"기출 2021-54"},{"x":"거푸집의 존치기간을 콘크리트 압축강도 기준으로 결정할 경우에 기둥, 보, 벽 등의 측면은 최소 14 MPa 이상으로 한다.","o":"측면은 5 MPa 이상이다. 14 MPa는 슬래브·보 밑면의 최소값이다.","src":"기출 2021-54"},{"x":"침하균열은 콘크리트의 표면에서 물의 증발속도가 블리딩 속도보다 빠른 경우에 발생한다.","o":"그 설명은 소성수축균열이다.","src":"기출 2021-56"},{"x":"소성수축균열은 굵은 철근 아래의 공극으로 콘크리트가 침하하여 철근 위에 발생한다.","o":"그 설명은 침하균열이다.","src":"기출 2021-56"},{"x":"하중에 의한 균열은 설계하중을 초과하거나 부동침하 등의 원인으로 생기며 주로 망상균열이 불규칙하게 발생한다.","o":"하중균열은 방향성이 있다. 망상균열은 소성수축·건조수축 균열이다.","src":"기출 2021-56"},{"x":"건조수축균열은 콘크리트 경화 전 수분의 증발에 의한 체적 증가로 발생한다.","o":"경화 후 수분 증발로 체적이 감소해 생긴다.","src":"기출 2021-56"},{"x":"콘크리트의 온도는 공기량에 영향을 주지 않는다.","o":"콘크리트 온도는 공기량에 영향을 준다.","src":"기출 2022-44"},{"x":"D35 철근은 인장 겹침 이음을 할 수 없다.","o":"D35 이하는 겹침이음이 가능하고, D35를 초과하는 철근은 겹침이음하지 않는다.","src":"기출 2022-45"},{"x":"기둥의 주근은 큰 보에 정착한다.","o":"기둥 주근은 기초에 정착한다.","src":"기출 2022-45"},{"x":"보의 주근은 슬래브에 정착한다.","o":"보의 주근은 기둥(큰 보)에 정착한다.","src":"기출 2022-45"},{"x":"갈고리로 가공하는 것은 인장과 압축 저항에 효과적이다.","o":"갈고리는 인장철근 정착에 효과적이고 압축에는 효과가 없다.","src":"기출 2022-45"},{"x":"늑근은 단부보다 중앙부에 많이 배근한다.","o":"전단력이 큰 단부에 많이 배근한다.","src":"기출 2023-43"},{"x":"전단철근이 배근된 보의 피복두께는 보 표면에서 주근 표면까지의 거리이다.","o":"스터럽(전단철근) 외면에서 보 표면까지의 거리다.","src":"기출 2023-44"},{"x":"SD400 철근은 항복강도 400 N/mm2인 원형철근이다.","o":"SD는 이형철근이다.","src":"기출 2023-44"},{"x":"나선기둥의 주근은 최소 4개로 한다.","o":"나선철근 기둥의 주근은 최소 6개다.","src":"기출 2023-44"},{"x":"1방향 슬래브의 배력철근은 단변방향으로 배근한다.","o":"배력철근은 장변방향, 주근은 단변방향이다.","src":"기출 2023-44"},{"x":"내력벽의 철근배근 간격은 벽두께의 5배 이하, 500 mm 이하로 한다.","o":"벽두께의 3배 이하, 450 mm 이하다.","src":"기출 2024-50"},{"x":"주철근에 갈고리를 둘 경우 인장철근보다는 압축철근의 정착길이 확보에 더 큰 효과가 있다.","o":"갈고리는 인장철근 정착에 효과가 있다.","src":"기출 2024-51"},{"x":"보단부의 사인장균열은 압축응력과 휨응력의 조합에 의한 응력으로 발생한다.","o":"전단력에 의한 주인장응력으로 발생한다.","src":"기출 2024-52"},{"x":"보단부의 사인장균열을 방지하기 위해 주로 수평철근으로 보강한다.","o":"스터럽(늑근)과 굽힘철근으로 보강한다.","src":"기출 2024-52"},{"x":"연직하중을 받는 단순보의 중앙부 상단에서 휨인장응력에 의한 수직방향의 균열이 발생한다.","o":"휨인장응력은 중앙부 하단에 생긴다.","src":"기출 2024-52"},{"x":"압축철근비가 클수록 장기처짐은 증가한다.","o":"압축철근비가 클수록 장기처짐은 감소한다.","src":"기출 2024-52"},{"x":"슬래브 주근은 배력철근 안쪽인 슬래브 중심 가까이 배근한다.","o":"슬래브 주근은 배력철근보다 바깥쪽에 배근한다.","src":"기출 2025-44"},{"x":"피복두께는 주근 중심에서 콘크리트 표면까지의 최단 거리를 말한다.","o":"최외측 철근 표면에서 콘크리트 표면까지의 최단거리다.","src":"기출 2025-45"},{"x":"작은 보(beam)의 주근을 기둥에 정착한다.","o":"작은 보의 주근은 큰 보에 정착한다.","src":"기출 2025-47"}]},"철골구조":{"묶음":[{"머리":"철골구조 특성","줄":[{"t":"단면에 비해 부재가 길고 두께가 얇아 좌굴되기 쉽다.","src":"기출 2021-57"},{"t":"접합부의 시공과 품질관리가 어려워 신중한 설계가 필요하다.","src":"기출 2021-57"},{"t":"강재의 취성파괴는 저온에서 인장을 받을 때나 응력이 집중되거나 하중이 갑자기 가해질 때 생기기 쉽다.","src":"기출 2021-57 | 보충"},{"t":"담금질: 강을 가열한 뒤 급랭해 강도와 경도를 높이는 열처리.","src":"기출 2021-57"},{"t":"탄소량이 늘면 강도는 증가하고 연성과 용접성은 감소한다.","src":"기출 2024-53 | 보충"}]},{"머리":"강재 종류와 항복강도","줄":[{"t":"SS 일반구조용 압연강재, SM 용접구조용 압연강재, SMA 용접구조용 내후성 열간압연강재, SN 건축구조용 압연강재, SHN 건축구조용 열간압연 H형강. SSC는 건축구조용 압연강재가 아니다.","src":"기출 2022-48, 2024-53"},{"t":"TMCP강: 극후판의 용접성과 내진성을 개선한 제어열처리강.","src":"기출 2024-53"},{"t":"판두께 16 mm 이하 SS275의 항복강도는 275 MPa이다.","src":"기출 2024-53"},{"t":"판두께 16 mm 초과 40 mm 이하: SM355는 345 MPa, SM275는 265 MPa.","src":"기출 2024-53, 2025-49"},{"t":"판두께 16 mm 이하: SM355 355 MPa, SM275 275 MPa.","src":"보충"}]},{"머리":"볼트 접합","줄":[{"t":"고장력볼트 접합은 부재 간 마찰력으로 응력을 전달하는 마찰접합이 기본이다.","src":"기출 2021-57"},{"t":"고장력볼트 표준볼트장력은 설계볼트장력을 10% 할증한 값이다.","src":"기출 2024-54"},{"t":"F10T-M24 볼트의 표준구멍 지름은 27 mm다(M22 이하는 지름 + 2 mm).","src":"기출 2024-54 | 보충"},{"t":"고장력볼트를 먼저 조인 뒤 용접하면 접합부 내력은 양쪽 내력의 합으로 본다. 용접을 먼저 하고 볼트를 나중에 조이면 용접이 전체 응력을 부담한다.","src":"기출 2022-46, 2024-54 | 보충"},{"t":"보통볼트 접합은 구조내력상 주요 부분 접합에 쓰지 않는다. 주요 부분은 고장력볼트나 용접으로 접합한다.","src":"기출 2022-46 | 보충"}]},{"머리":"용접","줄":[{"t":"필릿용접: 접합재의 면을 가공하지 않고 직각으로 겹쳐진 모서리 부분을 용접한다.","src":"기출 2022-47"},{"t":"필릿용접의 유효단면적 = 유효목두께 × 유효길이.","src":"기출 2024-54"},{"t":"플러그용접은 겹침이음에서 전단응력을 전달한다.","src":"기출 2024-54 | 보충"},{"t":"그루브(맞댐)용접은 접합재 끝면을 가공해 홈을 파고 용접한다. 크레이터는 용접 끝에 생기는 오목한 결함이다.","src":"기출 2022-47, 2023-45 | 보충"}]},{"머리":"부재와 부속","줄":[{"t":"H형강 보의 플랜지는 휨모멘트에, 웨브는 전단력에 저항한다.","src":"기출 2022-46"},{"t":"커버플레이트: 휨모멘트 저항 보강. 스티프너: 웨브 좌굴방지.","src":"기출 2023-45"},{"t":"쉬어커넥터·스터드 볼트는 철골보와 콘크리트 슬래브를 일체화하는 전단연결재다. 휨 연결철물이 아니다.","src":"기출 2022-46, 2023-45"},{"t":"허니콤보: H형강 웨브를 지그재그로 절단한 뒤 위아래를 어긋나게 용접해 육각형 구멍을 낸 보.","src":"기출 2022-49"},{"t":"래티스보, 격자보, 판보, 합성보는 허니콤보와 구별한다.","src":"기출 2022-49"}]},{"머리":"내화피복","줄":[{"t":"주거시설(공동주택) 보·기둥의 내화시간: 12층/50 m 초과 3시간, 12층/50 m 이하 2시간, 4층/20 m 이하 1시간.","src":"건축물의 피난·방화구조 등의 기준에 관한 규칙 별표 1"},{"t":"내화피복은 화재 때 지정된 시간 동안 철골 부재의 내력을 유지하려고 한다.","src":"기출 2023-55"},{"t":"뿜칠공법: 작업성이 우수하고 복잡한 형상에도 시공이 가능하며 값이 싸지만, 피복두께와 밀도 관리가 어렵다.","src":"기출 2021-58, 2023-55"},{"t":"성형판 붙임(건식)공법: 내화·단열성이 좋은 경량 성형판을 연결철물이나 접착제로 붙인다. 작업능률이 우수하나 재료 파손 우려가 있다.","src":"기출 2021-58, 2023-55"},{"t":"합성공법: 이종재료를 적층하거나 이질재료를 접합해 일체화한다.","src":"기출 2021-58"},{"t":"도장공법: 내화도료의 도막이 화재 때 발포·팽창해 단열층을 만든다.","src":"기출 2021-58"},{"t":"타설공법: 거푸집을 설치해 철골부재에 콘크리트 등을 타설한다.","src":"기출 2023-55"},{"t":"미장공법: 시공면적 5㎡당 1개소 단위로 핀 등을 꽂아 두께를 확인한다.","src":"기출 2023-55"}]}],"함정":[{"x":"강재의 취성파괴는 고온에서 인장할 때 또는 갑작스런 하중의 집중으로 생기기 쉽다.","o":"저온에서 인장을 받을 때나 하중이 갑자기 집중될 때 생기기 쉽다.","src":"기출 2021-57"},{"x":"12/50 [최고층수/최고높이(m)]를 초과하는 주거시설의 보ㆍ기둥은 2시간 이상의 내화 구조 성능기준을 만족해야 한다.","o":"12층/50 m 초과 주거시설의 보·기둥은 3시간 이상이다.","src":"기출 2021-58"},{"x":"고장력볼트를 먼저 시공한 후 용접을 한 경우, 응력은 용접이 모두 부담한다.","o":"볼트를 먼저 조인 뒤 용접하면 양쪽 내력의 합으로 본다. 용접이 전부 부담하는 경우는 용접을 먼저 한 때다.","src":"기출 2022-46"},{"x":"볼트 접합은 구조 안전성, 시공성 모두 우수하기 때문에 구조내력상 주요 부분 접합에 널리 적용된다.","o":"보통볼트는 주요 부분 접합에 쓰지 않고, 고장력볼트나 용접을 쓴다.","src":"기출 2022-46"},{"x":"일반구조용 압연강재: SS 용접구조용 압연강재: SM 건축구조용 압연강재: SSC","o":"건축구조용 압연강재는 SN이다.","src":"기출 2022-48"},{"x":"스터드 볼트(stud bolt): 휨 연결 철물","o":"스터드 볼트는 철골보와 슬래브를 잇는 전단연결재다.","src":"기출 2023-45"},{"x":"뿜칠공법은 복잡한 형상에도 시공이 가능하며 균일한 피복두께의 확보가 용이하다.","o":"뿜칠공법은 피복두께와 밀도 관리가 어렵다.","src":"기출 2023-55"},{"x":"강재의 화학적 성질에서 탄소량이 증가하면 강도는 감소하나, 연성과 용접성은 증가 한다.","o":"탄소량이 늘면 강도는 증가하고 연성과 용접성은 감소한다.","src":"기출 2024-53"},{"x":"고장력볼트 F10T-M24의 표준구멍지름은 26 mm이다.","o":"27 mm다.","src":"기출 2024-54"},{"x":"플러그용접은 겹침이음에서 전단응력보다는 휨응력을 주로 전달하게 해준다.","o":"플러그용접은 전단응력을 전달한다.","src":"기출 2024-54"},{"x":"필릿용접의 유효단면적은 유효목두께의 2배에 유효길이를 곱한 것이다.","o":"유효목두께 × 유효길이다.","src":"기출 2024-54"},{"x":"용접을 먼저 한 후 고장력볼트를 시공한 경우 접합부의 내력은 양쪽 접합내력의 합으로 본다.","o":"용접을 먼저 하면 용접이 전체 응력을 부담한다. 양쪽 합은 볼트를 먼저 조인 경우다.","src":"기출 2024-54"}]},"조적공사":{"묶음":[{"머리":"쌓기 방법","줄":[{"t":"엇모쌓기: 벽돌을 45° 각도로 모서리가 면에 나오게 쌓는다.","src":"기출 2022-50"},{"t":"영롱쌓기: 치장을 목적으로 벽돌벽에 구멍을 규칙적으로 내어 쌓는다.","src":"기출 2022-50, 2023-53"},{"t":"공간쌓기: 벽돌벽 중간에 공간을 두어 쌓는다. 바깥쪽을 주벽체로 하고 안쪽은 0.5B로 쌓는다.","src":"기출 2022-50, 2023-49, 2025-51"},{"t":"내쌓기: 장선·마루 등을 받치려고 벽돌을 벽면에서 내밀어 쌓는다. 1켜씩 1/8 B 또는 2켜씩 1/4 B 내쌓는다.","src":"기출 2022-50, 2025-51 | 보충"},{"t":"아치쌓기: 상부하중을 아치 축선을 따라 압축력으로 하부에 전달한다.","src":"기출 2022-50 | 보충"},{"t":"거친 아치쌓기는 보통 벽돌을 쓰고 줄눈을 쐐기 모양으로 한다. 벽돌을 쐐기 모양으로 다듬은 아치는 본아치다.","src":"기출 2023-49 | 보충"},{"t":"미식쌓기: 다섯 켜는 길이쌓기, 그 위 한 켜는 마구리쌓기.","src":"기출 2023-49"},{"t":"영식쌓기는 길이켜와 마구리켜를 번갈아 쌓고, 불식(프랑스식)쌓기는 한 켜에 길이와 마구리를 번갈아 놓는다.","src":"보충"}]},{"머리":"시공 기준","줄":[{"t":"하루 쌓기 높이는 1.2 m(18켜 정도)를 표준, 최대 1.5 m(22켜 정도) 이하로 한다.","src":"기출 2023-60"},{"t":"표준형 벽돌 크기는 190 mm × 90 mm × 57 mm, 줄눈 표준 너비는 10 mm다.","src":"기출 2023-60 | 보충"},{"t":"내력 조적벽은 통줄눈으로 시공하지 않고 막힌줄눈으로 한다.","src":"기출 2023-60 | 보충"},{"t":"치장줄눈 파기는 줄눈 모르타르가 굳기 전에 한다.","src":"기출 2023-60 | 보충"},{"t":"기초쌓기는 1/4 B씩 1켜 또는 2켜 내어 쌓고, 기초 벽돌 맨 밑면의 너비는 벽두께의 2배로 한다.","src":"기출 2025-51 | 보충"},{"t":"내화벽돌 줄눈너비는 6 mm를 표준으로 한다. 내화벽돌은 벽난로처럼 불에 직접 닿는 곳에 쓴다.","src":"기출 2024-56, 2025-51"},{"t":"창대벽돌 윗면은 15° 정도 경사지게 옆세워 쌓는다.","src":"기출 2025-51"},{"t":"벽량 = 내력벽 길이의 합 ÷ 그 층 바닥면적. 150 mm/㎡ 이상이어야 한다.","src":"기출 2023-49 | 보충"}]},{"머리":"백화현상","줄":[{"t":"백화 방지: 조립률이 큰 모래 사용, 분말도가 큰 시멘트 사용, 물시멘트비 감소, 차양·돌림띠 설치, 흡수율이 작고 소성이 잘된 벽돌 사용.","src":"기출 2021-44 | 보충"},{"t":"점토벽돌은 소성품이라 소성도가 품질 항목이 되고, 시멘트벽돌은 소성품이 아니다.","src":"기출 2023-49 | 보충"}]}],"함정":[{"x":"분말도가 작은 시멘트를 사용한다(백화 방지 대책).","o":"분말도가 큰 시멘트를 쓴다.","src":"기출 2021-44"},{"x":"아치쌓기는 상부하중을 아치의 축선을 따라 인장력으로 하부에 전달되게 쌓는 방식이다.","o":"아치는 축선을 따라 압축력으로 하중을 전달한다.","src":"기출 2022-50"},{"x":"벽량이란 내력벽 길이의 합을 그 층의 바닥면적으로 나눈 값으로 150 mm/m2 미만이 어야 한다.","o":"150 mm/㎡ 이상이어야 한다.","src":"기출 2023-49"},{"x":"공간쌓기에서 주 벽체는 정한 바가 없을 경우 안벽으로 한다.","o":"바깥쪽을 주벽체로 하고 안쪽을 0.5B 쌓기로 한다.","src":"기출 2023-49, 2025-51"},{"x":"점토 및 콘크리트 벽돌은 압축강도, 흡수율, 소성도의 품질기준을 모두 만족하여야 한다.","o":"소성도는 소성하는 점토벽돌에만 해당한다.","src":"기출 2023-49"},{"x":"거친 아치쌓기란 벽돌을 쐐기 모양으로 다듬어 만든 아치로 줄눈은 아치의 중심에 모이게 하여야 한다.","o":"벽돌을 쐐기 모양으로 다듬은 아치는 본아치다. 거친 아치는 줄눈을 쐐기 모양으로 한다.","src":"기출 2023-49"},{"x":"기초 쌓기는 1/4 B로 1켜 또는 2켜씩 내어 쌓으며 기초 벽돌 맨 밑면의 너비는 벽두께로 한다.","o":"맨 밑면 너비는 벽두께의 2배로 한다.","src":"기출 2025-51"}]},"미장·타일·도장공사":{"묶음":[{"머리":"미장 용어","줄":[{"t":"손질바름: 콘크리트·콘크리트블록 바탕에 초벌바름 하기 전, 마감두께를 균등하게 할 목적으로 모르타르 등으로 요철을 미리 조정하는 것.","src":"기출 2021-43"},{"t":"고름질은 초벌바름 후 심한 요철을 평탄하게 고르는 작업이다. 라스먹임은 메탈라스 등에 모르타르를 먹이는 작업, 규준바름은 평탄 기준을 만드는 바름, 실러바름은 바탕 흡수 조정이다.","src":"기출 2021-43 | 보충"},{"t":"덧먹임은 바름면의 갈라진 틈·구멍 등을 모르타르로 메우는 작업이다. 종석이 빠진 자리를 메우는 작업으로 정의하지 않는다.","src":"기출 2023-50 | 보충"}]},{"머리":"미장재료","줄":[{"t":"기경성 재료(공기 중 이산화탄소와 반응): 진흙질, 석회질(소석회·돌로마이트 플라스터). 수경성 재료: 석고질, 시멘트질.","src":"기출 2023-50, 2024-57"},{"t":"석고플라스터는 시멘트·소석회·돌로마이트플라스터와 혼합해 쓰면 안 된다. 수경성이며 경화가 빨라 작업시간이 짧다.","src":"기출 2023-50, 2024-57"},{"t":"경석고 플라스터(무수석고)는 경화속도가 빠르고 수축이 거의 없다.","src":"기출 2025-50"},{"t":"스터코 바름: 소석회에 대리석가루 등을 섞어 흙손으로 성형하는 외벽용 미장마감.","src":"기출 2023-50"},{"t":"단열 모르타르는 외단열이 내단열보다 효과적이다.","src":"기출 2023-50"}]},{"머리":"미장 시공","줄":[{"t":"시멘트 모르타르 바름은 초벌을 부배합, 재벌·정벌을 빈배합으로 해 부착력을 확보한다.","src":"기출 2024-57"},{"t":"살붙임바름은 한꺼번에 두껍게 바르지 않고 여러 번 나눠 바른다.","src":"기출 2024-57 | 보충"},{"t":"셀프레벨링재는 시공 중과 양생 중 통풍과 기류를 막아 급건조를 피한다.","src":"기출 2024-57 | 보충"},{"t":"바름면 흙손작업은 갈라지거나 들뜨는 것을 막으려고 바름층이 굳기 전에 끝낸다.","src":"기출 2025-50"},{"t":"콘크리트 바탕의 표면 경화 불량 두께가 2 mm 이하이면 와이어 브러시 등으로 불량부분을 제거한다.","src":"기출 2025-50"},{"t":"미장바름 주변 온도가 5℃ 이하이면 공사를 중단하거나 난방해 5℃ 이상으로 유지한다.","src":"기출 2025-50"}]},{"머리":"타일 종류·줄눈","줄":[{"t":"타일 흡수성이 높은 순서: 토기질 > 도기질 > 석기질 > 자기질.","src":"기출 2023-51"},{"t":"자기질 타일은 물기가 있는 곳과 외부에도 사용할 수 있다.","src":"기출 2024-58 | 보충"},{"t":"클링커 타일은 바닥용으로 적합하다.","src":"기출 2022-51"},{"t":"타일 줄눈너비: 대형벽돌형(외부) 9 mm, 대형(내부일반) 6 mm, 소형 3 mm, 모자이크 2 mm, 개구부 둘레·설비 기구류와의 마무리 줄눈 10 mm.","src":"기출 2021-45"}]},{"머리":"타일 시공","줄":[{"t":"붙임용 모르타르에 접착력을 높이려고 시멘트 가루를 뿌리지 않는다.","src":"기출 2022-51"},{"t":"흡수성이 있는 타일은 물을 축여 사용한다.","src":"기출 2022-51"},{"t":"접착제 붙임공법은 내장공사에 주로 쓴다. 개량압착 붙임공법은 바탕면과 타일 뒷면 모두에 붙임 모르타르를 발라 붙인다.","src":"기출 2022-51"},{"t":"치장줄눈은 타일 부착 3시간 정도 지난 뒤 줄눈파기를 한다. 타일붙임용 모르타르 배합비는 용적비로 계상한다.","src":"기출 2023-51"},{"t":"타일붙이기는 벽타일을 먼저, 바닥타일을 나중에 붙인다.","src":"기출 2023-51, 2024-58"},{"t":"모르타르 부착 타일공법의 붙임시간(open time)은 공법별로 다르게 관리한다.","src":"기출 2023-51"},{"t":"접착모르타르의 물시멘트비를 낮춰 동해를 막고, 줄눈누름을 충분히 해 빗물침투를 막는다.","src":"기출 2024-58"},{"t":"줄눈을 넣은 후 24시간 이내 비가 올 우려가 있으면 폴리에틸렌 필름 등으로 차단·보양한다.","src":"기출 2025-52"}]},{"머리":"타일 접착력 시험","줄":[{"t":"접착력 시험은 타일 시공 후 4주 이상일 때 실시한다.","src":"기출 2024-58, 2025-52"},{"t":"판정: 인장부착강도 0.39 N/㎟ 이상.","src":"기출 2025-52"},{"t":"일반건축물은 타일면적 200㎡당 1장씩 시험한다.","src":"기출 2025-52"},{"t":"시험할 타일 크기가 40 mm 미만이면 타일 4매를 1개조로 해 부속장치에 붙여 시험한다.","src":"기출 2025-52"}]},{"머리":"도장공사","줄":[{"t":"도료의 사용목적: 미관, 보호(방청·방수·내화·방부), 광택 등. 단면증가는 목적이 아니다.","src":"기출 2023-52"},{"t":"도장 하자: 은폐불량, 백화(블루밍), 기포, 핀홀 등. 피트는 도장공사의 하자 항목에 해당하지 않는다.","src":"기출 2021-51"},{"t":"바니시는 수지를 용제에 녹인 투명 도료다. 입체무늬 도막을 만든 에나멜이 아니다.","src":"기출 2024-45 | 보충"},{"t":"롤러도장은 붓도장보다 도장 속도가 빠르다.","src":"기출 2024-45 | 보충"},{"t":"안료는 물이나 용제에 녹지 않는 무채 또는 유채의 분말이다. 수지는 도막 형성 요소다.","src":"기출 2024-45 | 보충"},{"t":"철재면 바탕 만들기는 일반적으로 가공 장소에서 바탕재를 조립하기 전에 한다.","src":"기출 2024-45 | 보충"},{"t":"도료 견본품은 목재 바탕일 경우 100 mm × 200 mm 크기로 제출한다.","src":"기출 2024-45"}]}],"함정":[{"x":"고름질(미장공사에서 초벌 바름하기 전 마감두께를 균등하게 할 목적으로 요철을 조정)","o":"그 설명은 손질바름이다.","src":"기출 2021-43"},{"x":"대형벽돌형(외부) 타일의 줄눈너비는 10 mm이다.","o":"9 mm다.","src":"기출 2021-45"},{"x":"도장공사의 하자에 피트가 포함된다.","o":"피트는 도장 하자 항목이 아니다. 은폐불량·백화·기포·핀홀은 하자다.","src":"기출 2021-51"},{"x":"붙임용 모르타르에 접착력 향상을 위해 시멘트 가루를 뿌린다.","o":"시멘트 가루를 뿌리지 않는다.","src":"기출 2022-51"},{"x":"덧먹임이란 작업면의 종석이 빠져나간 자리를 메우기 위해 반죽한 것을 작업면에 발라 채우는 작업이다.","o":"덧먹임은 바름면의 갈라진 틈·구멍을 메우는 작업이다.","src":"기출 2023-50"},{"x":"모르타르로 부착하는 타일공법의 붙임시간(open time)은 모두 동일하게 관리한다.","o":"공법별로 다르게 관리한다.","src":"기출 2023-51"},{"x":"바니시(varnish)는 입체무늬 등의 도막이 생기도록 만든 에나멜이다.","o":"바니시는 수지를 용제에 녹인 투명 도료다.","src":"기출 2024-45"},{"x":"롤러도장은 붓도장보다 도장 속도가 느리지만 일정한 도막두께를 유지할 수 있다.","o":"롤러도장은 붓도장보다 속도가 빠르다.","src":"기출 2024-45"},{"x":"수지는 물이나 용체에 녹지 않는 무채 또는 유채의 분말이다.","o":"그 설명은 안료다.","src":"기출 2024-45"},{"x":"철재면 바탕 만들기는 일반적으로 가공 장소에서 바탕재 조립 후에 한다.","o":"조립 전에 한다.","src":"기출 2024-45"},{"x":"소석회, 돌로마이트 플라스터 등은 수경성 재료로서 가수에 의해 경화한다.","o":"소석회·돌로마이트 플라스터는 기경성이다.","src":"기출 2024-57"},{"x":"바탕처리 시 살붙임바름은 한꺼번에 두껍게 바르는 것이 좋다.","o":"여러 번 나눠 바른다.","src":"기출 2024-57"},{"x":"석고 플라스터는 기경성으로 경화속도가 느려 작업시간이 자유롭다.","o":"수경성이며 경화가 빨라 작업시간이 짧다.","src":"기출 2024-57"},{"x":"셀프레벨링재 사용 시 통풍과 기류를 공급해 건조시간을 단축하여 표면평활도를 높인다.","o":"통풍과 기류를 막아 급건조를 피한다.","src":"기출 2024-57"},{"x":"자기질 타일은 물기가 있는 곳과 외부에는 사용할 수 없다.","o":"자기질 타일은 물기 있는 곳과 외부에도 쓴다.","src":"기출 2024-58"},{"x":"압송뿜칠기계로 바름하는 두께가 20mm를 넘는 경우에 초벌, 정벌 2회로 나누어 뿜칠 바름을 한다.","o":"출제 오답 문장이다(정확한 두께·횟수 기준은 미장공사 시방서 확인 필요).","src":"기출 2025-50"},{"x":"접착력 시험은 타일 시공 후 3주 이상일 때 실시한다.","o":"4주 이상이다.","src":"기출 2025-52"}]},"방수·방습공사":{"묶음":[{"머리":"공법 비교","줄":[{"t":"아스팔트 방수: 아스팔트 용융공정이 필요하고, 공정이 복잡하며, 멤브레인 방수의 일종이다. 결함부 발견이 어렵고 보호누름층이 필요하다.","src":"기출 2021-49, 2022-55, 2023-58"},{"t":"시멘트 액체방수는 아스팔트 방수보다 신축성이 작고, 균열이 많이 생기며, 공사비가 싸고 공사 시간이 짧다. 결함부는 발견하기 쉽다.","src":"기출 2023-59"},{"t":"시멘트 액체방수는 모체에 균열이 생기면 방수층도 손상된다.","src":"기출 2022-55"},{"t":"도막방수: 도료 상태의 방수재를 여러 번 발라 방수막을 형성한다. 이음매가 없어 일체성이 좋다.","src":"기출 2022-55, 2023-58"},{"t":"실링방수: 접합부, 줄눈, 균열부위에 적용한다.","src":"기출 2022-55"},{"t":"멤브레인 방수: 불투수성 피막을 만드는 방수.","src":"기출 2024-43"},{"t":"기상조건은 방수층의 품질과 성능에 큰 영향을 준다.","src":"기출 2023-58"}]},{"머리":"안방수와 바깥방수","줄":[{"t":"바깥방수: 수압이 크고 깊은 지하실에 적합하다. 본 공사보다 먼저 방수하므로 공사시기에 제약이 있고 공사비가 비싸며 보호누름이 필요 없다.","src":"기출 2021-50, 2022-55, 2023-58 | 보충"},{"t":"안방수: 수압이 작고 얕은 지하실에 적합하다. 공사시기가 자유롭고 공사비가 싸며 시공이 쉽고 보호누름이 필요하다.","src":"기출 2021-50, 2024-43"}]},{"머리":"재료·부자재","줄":[{"t":"아스팔트 프라이머는 방수층과 바탕면의 부착력을 높이는 역할을 한다.","src":"기출 2023-58, 2024-43"},{"t":"백업재: 실링재의 줄눈 깊이를 소정의 위치로 유지하려고 줄눈에 채우는 성형 재료.","src":"기출 2024-43"},{"t":"개량아스팔트시트 방수 시공순서: 바탕처리 → 프라이머 도포 → 개량아스팔트시트 붙이기 → 특수부위 처리 → 보호 및 마감.","src":"기출 2022-56"},{"t":"신축성 시트계 방습자재: 비닐 필름 방습지, 폴리에틸렌 방습층, 방습층 테이프.","src":"기출 2024-44"},{"t":"누수균열 보수 주입재: 합성고무계 폴리머 겔, 수계 아크릴 겔, 친수성 에폭시 수지계, 폴리(발포) 우레탄계. 벤토나이트 겔은 해당하지 않는다.","src":"기출 2025-56"}]},{"머리":"바탕 조건","줄":[{"t":"구배는 방수층이 아니라 구조체에 두어 하중 증가를 막고 배수를 원활하게 한다.","src":"기출 2025-55"},{"t":"바탕표면의 요철은 제거해야 방수재료와 잘 붙는다.","src":"기출 2025-55"},{"t":"바탕 청소에 고압 물세척을 쓸 수 있다.","src":"기출 2025-55"},{"t":"바탕표면 강도가 부족하면 보강한 뒤 방수한다.","src":"기출 2025-55"}]}],"함정":[{"x":"아스팔트 방수공법은 결함부 발견이 용이하다.","o":"결함부 발견이 어렵다.","src":"기출 2021-49"},{"x":"안방수공법은 수압이 크고 깊은 지하실에 적합하다.","o":"수압이 크고 깊은 지하실에는 바깥방수가 적합하다.","src":"기출 2021-50, 2023-58"},{"x":"시멘트액체방수는 모체에 균열이 발생하여도 방수층 손상이 효과적으로 방지된다.","o":"모체 균열이 생기면 방수층도 손상된다.","src":"기출 2022-55"},{"x":"기상조건은 방수층의 품질 및 성능에 큰 영향을 미치지 않는다.","o":"큰 영향을 미친다.","src":"기출 2023-58"},{"x":"도막 방수공법은 이음매가 있어 일체성이 좋지 않다.","o":"이음매가 없어 일체성이 좋다.","src":"기출 2023-58"},{"x":"아스팔트 방수는 보호누름이 필요하지 않다.","o":"보호누름이 필요하다.","src":"기출 2023-58"},{"x":"시멘트 액체방수 시 치켜올림 부위의 겹침폭은 30 mm 이상으로 한다.","o":"출제 오답 문장이다(겹침폭 기준은 방수공사 시방서 확인 필요).","src":"기출 2024-43"},{"x":"건조한 바탕을 전제로 할 때, 바탕면 함수상태는 12 % 이하로 관리하여야 한다.","o":"출제 오답 문장이다(건조 바탕 함수율 기준은 방수공사 시방서 확인 필요).","src":"기출 2025-55"},{"x":"바탕표면에 발생한 요철은 방수재료와의 부착에 유리하므로 존치해도 된다.","o":"요철은 제거한다.","src":"기출 2025-55"},{"x":"바탕청소를 위한 고압 물세척은 방수에 불리하므로 실시하지 않는다.","o":"고압 물세척을 쓸 수 있다.","src":"기출 2025-55"},{"x":"바탕표면 강도가 부족하더라도 방수층으로 덮이므로 청소 후 방수공사를 진행한다.","o":"강도가 부족하면 보강한 뒤 방수한다.","src":"기출 2025-55"}]},"창호·유리공사":{"묶음":[{"머리":"창호철물","줄":[{"t":"경첩은 문짝을 문틀에 달 때 여닫는 축 역할을 한다. 축은 핀(pin)이고, 핀을 둘러감은 부분은 너클이다.","src":"기출 2022-54 | 보충"},{"t":"자유경첩(스프링 힌지): 스프링을 장치해 안팎으로 자유롭게 여닫는다.","src":"기출 2022-54"},{"t":"플로어힌지: 바닥에 설치해 한쪽에서 열면 저절로 닫히며 중량이 큰 자재문에 쓴다.","src":"기출 2022-54"},{"t":"피봇힌지: 암수 돌쩌귀를 끼워 회전으로 여닫으며 중량문에 쓴다. 자동으로 닫히게 하는 철물이 아니다.","src":"기출 2022-54, 2023-56, 2024-41"},{"t":"레버토리 힌지: 저절로 닫히지만 10~15 cm 정도 열려 있게 하는 철물.","src":"기출 2021-59, 2024-41"},{"t":"도어체크(도어클로저): 문짝과 문 위틀에 설치해 문을 자동으로 닫는다. 피스톤 장치로 개폐속도를 조절할 수 있다.","src":"기출 2023-56, 2024-41"},{"t":"도어스톱: 벽 또는 문을 파손으로부터 보호한다.","src":"기출 2023-56"},{"t":"크레센트: 미서기창과 오르내리창의 잠금장치.","src":"기출 2023-56"},{"t":"풍소란: 미서기 창호의 마중대와 여밈대가 접하는 부분에 틈새가 생기지 않도록 방풍하는 부재.","src":"기출 2024-41, 2025-54"},{"t":"멀리온: 창 면적이 클 때 스틸바만으로 부족해 강판을 중공형으로 접어 가로 또는 세로로 대는 보강재.","src":"기출 2021-59"},{"t":"여닫이 창호철물: 플로어 힌지, 피벗 힌지, 도어 클로저. 도어 행거는 여닫이가 아니라 미닫이문 철물이다.","src":"기출 2021-59 | 보충"},{"t":"주름문은 방범 목적으로 쓴다.","src":"기출 2024-41"},{"t":"알루미늄 창호는 알칼리에 약하므로 모르타르·콘크리트와 직접 접촉시키지 않는다.","src":"기출 2021-59, 2023-56"}]},{"머리":"문 종류","줄":[{"t":"플러시문: 문틀을 짜고 양면에 합판을 붙여 평평하게 만든 문.","src":"기출 2022-52"},{"t":"양판문은 문틀 사이에 양판(판자)을 끼운 문이다.","src":"보충"}]},{"머리":"창호 시공","줄":[{"t":"창호철물 설치 시 앵커 간격은 모서리 150 mm 내외, 중앙 500 mm 내외.","src":"기출 2025-54"},{"t":"문틀은 위틀·선틀·밑틀로 구성되고, 고창·옆문이 있으면 중간틀·중간선틀이 추가된다.","src":"기출 2025-54"},{"t":"합판·집성재가 아닌 목재의 함수율은 설계도서에 정한 바가 없으면 18% 이하로 한다.","src":"기출 2025-54"},{"t":"4℃ 미만에서 실란트를 시공할 때는 피접착 표면을 용제로 닦은 뒤 마른 걸레로 닦고 담당원 승인을 받는다.","src":"기출 2025-53"},{"t":"실란트 작업은 상대습도가 90% 이상이면 하지 않는다.","src":"기출 2025-53"},{"t":"복층유리는 20매 이상 겹쳐 적치하지 않는다.","src":"기출 2025-53"},{"t":"배수구멍(weep hole)은 일반적으로 지름 5 mm 이상, 2개 이상으로 한다.","src":"기출 2025-53"},{"t":"세팅블록은 유리 폭의 1/4 지점에 각각 1개씩 설치해 유리 하단이 하부 프레임에 닿지 않게 한다.","src":"기출 2025-53 | 보충"}]},{"머리":"유리 종류","줄":[{"t":"강화유리: 판유리를 연화점 이상으로 가열한 뒤 급랭해 표면에 강한 압축응력층을 만든 유리.","src":"기출 2021-60, 2023-57, 2024-42"},{"t":"배강도유리: 연화점 이상에서 열처리 후 서냉해 압축응력층을 만든 유리. 절단이 불가능하다. 강도는 보통 판유리의 약 2배이며 강화유리보다 낮다.","src":"기출 2021-60, 2024-42 | 보충"},{"t":"접합유리: 유리 사이에 접합필름을 넣어 파손 때 파편 비산을 막는다. 방탄유리는 접합유리의 일종이다.","src":"기출 2021-60, 2023-57, 2024-42"},{"t":"복층유리: 단열·보온·방음·결로 방지 효과가 우수하다. 간격을 유지하고 흡습제를 담는 부재는 스페이서이며 가스켓이 아니다.","src":"기출 2021-60, 2023-57 | 보충"},{"t":"로이(Low-E)유리: 열적외선을 반사하는 은소재 도막을 코팅해 단열효과를 높이고 가시광선 투과율을 높인 에너지 절약형 유리. 코팅면은 복층유리 공기층 쪽에 둔다.","src":"기출 2021-60, 2023-57, 2024-42 | 보충"},{"t":"열선흡수유리: 판유리에 소량의 금속산화물을 첨가해 적외선이 잘 투과되지 않는다.","src":"기출 2022-53, 2023-57"},{"t":"열선반사유리: 판유리 표면에 금속산화물 박막을 코팅해 경면효과가 난다.","src":"기출 2022-53"},{"t":"스팬드럴유리: 판유리 한쪽 면에 세라믹질 도료를 코팅해 불투명하게 만든 유리.","src":"기출 2022-53"},{"t":"유리블록: 보온, 채광, 의장 효과가 있다.","src":"기출 2024-42"}]}],"함정":[{"x":"가스켓은 유리의 간격을 유지하며 흡습제의 용기가 되는 재료를 말한다.","o":"그 설명은 스페이서다. 가스켓은 유리를 창틀에 고정하고 기밀을 유지하는 재료다.","src":"기출 2021-60"},{"x":"로이(Low-E)유리는 특수금속 코팅막을 실외측 유리의 외부면에 두어 단열효과를 극대화한 것이다.","o":"코팅면은 복층유리 공기층 쪽에 둔다.","src":"기출 2021-60"},{"x":"강화유리는 판유리를 연화점 이하의 온도에서 열처리한 후 급랭시켜 유리 표면에 강한 압축응력 층을 만든 것이다.","o":"연화점 이상으로 가열한 뒤 급랭한다.","src":"기출 2021-60"},{"x":"배강도유리는 판유리를 연화점 이상의 온도에서 열처리한 후 서냉하여 유리 표면에 압축응력 층을 만든 것으로 내풍압이 우수하다.","o":"2021년 기출에서 오답으로 처리된 문장이다. 배강도유리는 서냉, 절단 불가, 강도는 보통 판유리의 약 2배로 기억한다.","src":"기출 2021-60"},{"x":"경첩의 축이 되는 것은 핀(pin)이고, 핀을 보호하기 위해 둘러감은 것이 행거(hanger) 이다.","o":"핀을 둘러감은 부분은 너클이다.","src":"기출 2022-54"},{"x":"피봇 힌지(pivot hinge)는 문을 자동으로 닫히게 하는 경첩으로 중량의 자재문에 사용 한다.","o":"자동으로 닫는 것은 플로어힌지·도어체크다. 피봇힌지는 암수 돌쩌귀로 회전해 여닫는다.","src":"기출 2023-56"},{"x":"열선반사유리는 소량의 금속산화물을 첨가하여 적외선이 잘 투과되지 않는 성질을 갖는다.","o":"그 설명은 열선흡수유리다.","src":"기출 2023-57"},{"x":"강화유리는 판유리를 연화점 이상으로 가열 후 서서히 냉각시켜 열처리한 유리이다.","o":"급랭한다. 서냉은 배강도유리다.","src":"기출 2024-42"},{"x":"도어체크는 피스톤장치가 있지만 개폐속도는 조절할 수 없다.","o":"개폐속도를 조절할 수 있다.","src":"기출 2024-41"},{"x":"수장용 집성재의 두께 및 너비에 대한 치수의 허용치는 ±2.0 mm 이하이다.","o":"출제 오답 문장이다(허용치 수치는 시방서 확인 필요).","src":"기출 2025-54"},{"x":"세팅블록은 유리 폭의 □ 지점에 각각 1개씩 설치하여 유리의 하단부가 하부 프레임에 닿지 않도록 한다.","o":"유리 폭의 1/4 지점에 설치한다(원문 분수 표기가 누락돼 있음).","src":"기출 2025-53"}]},"지붕·홈통·천장공사":{"묶음":[{"머리":"지붕 물매(경사)","줄":[{"t":"되물매는 경사 1:1(45°)의 물매다. 1:2 물매가 아니고 30°도 아니다.","src":"기출 2021-52, 2024-59"},{"t":"평물매는 경사 45° 미만의 물매이고, 반물매는 평물매(1:1)의 1/2인 1:2 물매다.","src":"기출 2021-52"},{"t":"지붕경사는 수평방향 길이에 대한 수직방향 높이의 비다(수직높이에 대한 수평길이가 아니다).","src":"기출 2025-58"},{"t":"지붕경사 분류 용어: 평지붕, 완경사지붕, 일반경사지붕, 급경사지붕. 2021년 기출에서는 평지붕 경사 1/6 이하, 급경사지붕 경사 3/4 이상이 옳은 문장이었다.","src":"기출 2021-52, 2025-58"},{"t":"지붕면적이 클수록 물매는 크게 하는 것이 좋다.","src":"기출 2024-59 | 보충"}]},{"머리":"지붕 모양","줄":[{"t":"맨사드(mansard)지붕: 모임지붕의 물매를 상하 다르게 한 지붕으로 천장 속을 높게 쓸 수 있고 비교적 큰 실내구성에 용이하다.","src":"기출 2022-58"},{"t":"지붕 위에 작은 지붕을 설치한 형태는 솟을지붕이다. 박공지붕은 용마루 양쪽으로 경사진 지붕이다.","src":"기출 2022-58, 2024-59 | 보충"},{"t":"보기에 나온 다른 지붕: 합각지붕, 꺾임지붕, 부섭지붕.","src":"기출 2022-58"}]},{"머리":"금속지붕·홈통","줄":[{"t":"수평 거멀접기는 이음 방향이 배수 방향과 평행한 방향으로 설치한다(기출 정답 기준).","src":"기출 2024-59"},{"t":"장식홈통은 선홈통 상부에 설치하며, 장식 기능 외에 우수방향을 돌리거나 넘쳐흐름을 방지한다.","src":"기출 2024-59"}]},{"머리":"천장","줄":[{"t":"M-Bar공법: 천장판 이음이 밀착되어 방음효과가 우수한 매립형 경량천장 공법.","src":"기출 2025-57"},{"t":"T-Bar공법은 천장판 이음 부분이 노출되는 방식이다.","src":"기출 2025-57 | 보충"}]}],"함정":[{"x":"되물매는 경사 1 : 2 물매이다.","o":"되물매는 1:1(45°)이다.","src":"기출 2021-52"},{"x":"지붕면적이 클수록 물매는 작게 하는 것이 좋다.","o":"클수록 물매를 크게 한다.","src":"기출 2024-59"},{"x":"되물매란 경사가 30° 일 때의 물매를 말한다.","o":"45°(1:1)다.","src":"기출 2024-59"},{"x":"지붕 위에 작은 지붕을 설치하는 것은 박공지붕이다.","o":"솟을지붕이다.","src":"기출 2024-59"},{"x":"장식홈통은 선홈통 하부에 설치되며, 장식기능 이외에 우수방향을 돌리거나 넘쳐흐름을 방지한다.","o":"선홈통 상부에 설치한다.","src":"기출 2024-59"},{"x":"지붕경사란 수직방향의 높이에 대한 수평방향 길이의 비이다.","o":"수평방향 길이에 대한 수직방향 높이의 비다.","src":"기출 2025-58"},{"x":"평지붕이란 지붕의 경사가 □ 이하인 지붕이다.","o":"2025년 기출에서 오답으로 처리됨(원문 분수 표기 누락). 2021년 기출 기준은 1/6 이하.","src":"기출 2025-58"},{"x":"완경사지붕이란 경사가 □ ～ □ 미만인 지붕이다.","o":"2025년 기출에서 오답으로 처리됨(원문 분수 표기 누락).","src":"기출 2025-58"},{"x":"급경사지붕이란 경사가 □ 이상인 지붕이다","o":"2025년 기출에서 오답으로 처리됨(원문 분수 표기 누락). 2021년 기출 기준은 3/4 이상.","src":"기출 2025-58"}]},"적산(수량산출)":{"묶음":[{"머리":"적산과 견적","줄":[{"t":"적산: 공사에 필요한 재료와 품(노무)의 수량을 산출하는 것.","src":"기출 2022-59"},{"t":"명세견적: 완성된 설계도서, 현장설명, 질의응답 등으로 정밀하게 공사비를 산출한다.","src":"기출 2022-59"},{"t":"개산견적: 설계도서가 미비하거나 정밀 적산이 어려울 때, 과거 유사건물 자료를 참고해 공사비를 개략 산출한다.","src":"기출 2022-59, 2024-46"},{"t":"품셈: 단위공사량에 소요되는 재료·노무·기계력의 수량이다. 단가와는 무관하다.","src":"기출 2022-59, 2023-48"},{"t":"일위대가: 재료비에 가공·설치비 등을 가산해 만든 단위단가.","src":"기출 2022-59"},{"t":"아파트 적산은 단위세대에서 전체로 산출한다.","src":"기출 2024-46"}]},{"머리":"공사비 구성","줄":[{"t":"공사원가는 재료비·노무비·경비의 합이다. 일반관리비와 이윤은 공사원가에 포함하지 않는다.","src":"기출 2024-46 | 보충"},{"t":"본사 및 현장의 여비, 교통비, 통신비는 경비에 포함된다.","src":"기출 2023-48 | 보충"},{"t":"이윤은 노무비·경비·일반관리비 합계액의 15%를 초과해 계상할 수 없다.","src":"기출 2023-48"},{"t":"비계, 거푸집 같은 가설재는 간접재료비에 포함된다.","src":"기출 2024-46"},{"t":"직접노무비에는 현장감독자의 기본급이 포함되지 않는다.","src":"기출 2024-46"},{"t":"10㎡ 이하의 소단위 건축공사는 최대 50%까지 품을 할증할 수 있다.","src":"기출 2023-48"}]},{"머리":"재료 할증률","줄":[{"t":"할증률이 큰 순서: 판재 > 각재 > 붉은벽돌 > 유리.","src":"기출 2023-48"},{"t":"판재 10%, 각재 5%, 붉은벽돌 3%, 유리 1%.","src":"기출 2023-48 | 보충"},{"t":"3%: 이형철근, 일반합판, 고장력볼트.","src":"기출 2025-59 | 보충"},{"t":"5%: 기와, 비닐타일, 봉강.","src":"기출 2025-59 | 보충"},{"t":"시멘트벽돌 5%, 블록 4%, 원형철근 5%, 수장용 합판 5%.","src":"보충"}]},{"머리":"재료 단위 중량","줄":[{"t":"철근콘크리트 2,400 kg/㎥, 보통 콘크리트 2,300 kg/㎥, 시멘트 모르타르 2,100 kg/㎥, 시멘트(자연상태) 1,500 kg/㎥, 물 1,000 kg/㎥.","src":"기출 2021-46 | 보충"}]},{"머리":"벽돌·타일 수량 계산","줄":[{"t":"표준형 벽돌(190×90×57, 줄눈 10 mm) 정미량: 0.5B 75매/㎡, 1.0B 149매/㎡, 1.5B 224매/㎡, 2.0B 298매/㎡.","src":"기출 2022-60, 2024-47 | 보충"},{"t":"길이 8 m, 높이 2.5 m, 두께 2.0B(시멘트벽돌 1.5B + 붉은벽돌 0.5B): 면적 20㎡ → 시멘트벽돌 4,480매, 붉은벽돌 1,500매.","src":"기출 2022-60"},{"t":"길이 6 m, 높이 2 m, 1.0B: 12㎡ × 149 = 1,788매.","src":"기출 2024-47"},{"t":"타일 정미수량 = 면적 ÷ {(타일 가로 + 줄눈) × (타일 세로 + 줄눈)}.","src":"기출 2023-54, 2025-60"},{"t":"11.2 m × 6.4 m 2개소, 150 mm 타일, 줄눈 10 mm: 143.36㎡ ÷ 0.0256㎡ = 5,600매.","src":"기출 2023-54"},{"t":"6.3 m × 3.1 m 3개소, 300×200 mm 타일, 줄눈 10 mm: 58.59㎡ ÷ 0.0651㎡ = 900매.","src":"기출 2025-60"}]}],"함정":[{"x":"본사 및 현장의 여비, 교통비, 통신비는 일반관리비에 포함된다.","o":"경비에 포함된다.","src":"기출 2023-48"},{"x":"공사원가는 일반관리비와 이윤을 포함한다.","o":"공사원가는 재료비·노무비·경비다.","src":"기출 2024-46"},{"x":"품셈은 단위공사량에 소요되는 재료, 인력 및 기계력 등을 단가로 표시한 것이다.","o":"수량으로 표시한 것이다.","src":"기출 2022-59"},{"x":"보통 콘크리트의 추정 단위 중량은 2,200 kg/㎥이다.","o":"2,300 kg/㎥다.","src":"기출 2021-46"}]},"건축설비 기초(열·유체역학)":{"묶음":[{"머리":"물의 성질·열","줄":[{"t":"순수한 물은 1기압에서 4℃일 때 밀도가 가장 크고 부피는 최소다.","src":"기출 2022-63, 2023-63 | 보충"},{"t":"1기압에서 물 온도를 4℃에서 100℃로 높이면 체적은 약 4.3% 팽창한다.","src":"기출 2025-61"},{"t":"절대온도(K) = 섭씨온도 + 273.15. 459.7을 더하는 것은 화씨→랭킨 변환이다.","src":"기출 2022-63 | 보충"},{"t":"현열: 상태 변화 없이 온도 변화에만 쓰이는 열량. 잠열: 상태 변화에 쓰이는 열량.","src":"기출 2022-63, 2025-61"},{"t":"비열: 단위 질량(1 kg)의 물체 온도를 1℃ 올리는 데 필요한 열량. 열용량: 물체 전체의 온도를 1℃ 올리는 데 필요한 열량.","src":"기출 2021-65, 2022-63, 2025-61"},{"t":"비체적 = 체적 ÷ 질량.","src":"기출 2021-65, 2022-63, 2025-61"},{"t":"ppm은 백만분의 일이다.","src":"기출 2025-61"},{"t":"고위발열량: 연료가 연소할 때 생기는 수증기의 잠열을 포함한 총발열량.","src":"기출 2021-65"}]},{"머리":"유체","줄":[{"t":"정지한 물 속 임의의 점의 압력은 모든 방향으로 같고 수면으로부터의 깊이에 비례한다.","src":"기출 2023-63"},{"t":"관경이 달라지는 수평관에서 물이 정상 흐름이면 관경이 클수록 유속이 느리다.","src":"기출 2023-63"},{"t":"마찰손실수두(Darcy-Weisbach) h = λ(L/d)(v²/2g). 배관 길이·마찰계수에 비례, 관 내경·중력가속도에 반비례, 유속의 제곱에 비례.","src":"기출 2022-62, 2023-63, 2024-70"},{"t":"마찰손실수두 계산: λ0.04, L100 m, d0.05 m, v1.4 m/s → 8.0 mAq.","src":"기출 2025-63"},{"t":"국부저항: 직관부 이외의 구부러지는 부분, 분기부 등에서 생기는 저항.","src":"기출 2021-65"},{"t":"소켓: 같은 관경의 배관을 직선으로 접속할 때 쓰는 이음쇠.","src":"기출 2021-65"},{"t":"공동현상(캐비테이션): 배관 내 유체 압력이 그 온도의 포화증기압보다 낮아져 일부가 증발해 기포가 생기는 현상.","src":"기출 2021-65"}]},{"머리":"열관류","줄":[{"t":"열관류율 K = 1 ÷ 열관류저항 R. R = 1/αi + Σ(d/λ) + 1/αo.","src":"보충"},{"t":"열관류율 0.25 → 0.16 W/㎡K 개선: R이 4.0 → 6.25 ㎡K/W로 2.25 증가. 열전도율 0.04 W/mK 단열재라면 90 mm 추가.","src":"기출 2023-65"},{"t":"열관류저항 3.5 ㎡K/W 벽에 0.04 W/mK, 60 mm 단열재를 보강: R = 3.5 + 0.06/0.04 = 5.0 → K = 0.20 W/㎡K.","src":"기출 2024-79"},{"t":"실내측 표면온도 = 실내온도 − K(실내온도 − 외기온도) ÷ 실내측 표면 열전달율. 23 − 0.5×28÷8.0 = 21.25 → 21.3℃.","src":"기출 2025-65"}]}],"함정":[{"x":"서징현상은 배관 내를 흐르는 유체의 압력이 그 온도에서의 유체의 포화증기압보다 낮아질 경우 그 일부가 증발하여 기포가 발생하는 것이다.","o":"그 설명은 공동현상(캐비테이션)이다.","src":"기출 2021-65"},{"x":"순수한 물은 1기압 하에서 4 ℃일 때 가장 무겁고 부피는 최대가 된다.","o":"4℃에서 부피가 최소다.","src":"기출 2022-63"},{"x":"섭씨 절대온도는 섭씨온도에 459.7을 더한 값이다.","o":"273.15를 더한다.","src":"기출 2022-63"},{"x":"물체의 상태 변화 없이 온도가 변화할 때 필요한 열량은 잠열이다.","o":"현열이다.","src":"기출 2022-63"},{"x":"열용량은 단위 중량 물체의 온도를 1 ℃ 올리는데 필요한 열량이다.","o":"그 설명은 비열이다.","src":"기출 2022-63"},{"x":"순수한 물은 1기압 하에서 4 ℃일 때 밀도가 가장 작다.","o":"밀도가 가장 크다.","src":"기출 2023-63"},{"x":"배관의 마찰손실수두는 유체의 속도에 비례한다.","o":"유속의 제곱에 비례한다.","src":"기출 2024-70"},{"x":"농도를 나타내는 단위인 ppm은 천만분의 일의 양을 의미한다.","o":"백만분의 일이다.","src":"기출 2025-61"}]},"급수설비":{"묶음":[{"머리":"급수방식","줄":[{"t":"수도직결방식: 수도 본관의 압력에 따라 급수압이 변한다. 정전돼도 급수된다. 수질오염 가능성이 낮다.","src":"기출 2023-61, 2024-62 | 보충"},{"t":"고가수조방식: 위층과 아래층의 수압이 다르다(아래층이 높다). 다른 방식보다 수질오염 가능성이 높다.","src":"기출 2023-61, 2024-62"},{"t":"펌프직송방식: 단수 시 저수조에 남은 양만큼 급수할 수 있고, 옥상층 하중을 고려할 필요가 없다. 정전 시 비상발전기가 없으면 급수가 안 된다.","src":"기출 2021-66, 2023-61"},{"t":"고층건물 급수 조닝: 급수계통을 나누는 것이 바람직하다. 방법으로 감압밸브 방식이 있다. 안전밸브는 조닝 방법이 아니다.","src":"기출 2021-62, 2021-66, 2024-62"},{"t":"동시사용률은 위생기기의 개수가 늘수록 작아진다.","src":"기출 2024-62 | 보충"},{"t":"기구급수부하단위는 같은 종류의 기구라면 공중용이 개인용보다 크다.","src":"기출 2021-62"}]},{"머리":"펌프","줄":[{"t":"펌프 2대 병렬 운전: 유량과 양정이 모두 증가하나 증가폭은 배관계 저항에 따라 달라진다. 유량이 2배·양정이 0.5배 등으로 정해지지 않는다.","src":"기출 2021-61"},{"t":"상사법칙: 유량 Q ∝ N, 양정 H ∝ N², 축동력 P ∝ N³ (N은 회전수).","src":"기출 2021-66, 2022-77, 2023-62, 2024-64"},{"t":"회전수 2배: 양정 4배, 축동력 8배. 회전수 10% 증가: 양정 21% 증가(1.1²), 축동력 약 33% 증가(1.1³).","src":"기출 2021-66, 2023-62, 2024-64"},{"t":"펌프 양수량은 회전수에 비례한다.","src":"기출 2022-77"},{"t":"원심식 펌프: 볼류트 펌프, 터빈 펌프. 터보형 펌프에 해당한다.","src":"기출 2022-77, 2025-67"},{"t":"피스톤·플런저·다이어프램 펌프는 왕복식 용적형, 기어 펌프는 회전식 용적형이다.","src":"기출 2025-67 | 보충"},{"t":"공동현상(cavitation) 방지: 흡입양정을 낮춘다. 펌프 설치 위치를 수조 수위보다 낮게 한다.","src":"기출 2021-62, 2022-77, 2023-62 | 보충"},{"t":"서징(surging)이 생기면 배관 내 유량과 압력이 변동한다. 방지하려면 관로의 불필요한 잔류 공기를 제거한다.","src":"기출 2022-77, 2023-62"},{"t":"펌프 성능곡선: 양수량(토출량)에 대한 양정·효율·축동력의 관계를 나타낸다. 관경, 유속, 비체적과의 관계가 아니다.","src":"기출 2022-77 | 보충"},{"t":"실양정 = 흡입양정 + 토출양정. 전양정 = 실양정 + 배관 손실수두(+속도수두).","src":"기출 2023-62 | 보충"}]},{"머리":"밸브·이음","줄":[{"t":"볼 밸브: 핸들을 90도 돌리면 완전히 열리는 구조.","src":"기출 2022-78"},{"t":"스트레이너: 배관 중의 먼지, 토사, 쇠 부스러기를 걸러낸다.","src":"기출 2022-78, 2023-76"},{"t":"버터플라이 밸브: 내부 원판을 회전시켜 흐름을 조절한다.","src":"기출 2022-78"},{"t":"체크 밸브는 유체의 역류를 막는다. 스윙형은 수평·수직 배관 모두, 리프트형은 수평배관에만 쓴다.","src":"기출 2022-78, 2023-76"},{"t":"게이트 밸브는 글로브 밸브보다 유체 저항이 작다. 주로 개폐용이고 유량조절에는 글로브 밸브를 쓴다.","src":"기출 2022-78 | 보충"},{"t":"플랜지 이음: 배관과 밸브 등을 접속하고 교체·해체가 자주 있는 곳에서 볼트와 너트로 접합한다.","src":"기출 2022-79"},{"t":"벽을 관통하는 배관에는 슬리브를 설치한다.","src":"기출 2021-62"}]},{"머리":"수질·위생","줄":[{"t":"크로스 커넥션(음용수 배관과 다른 배관의 직접 연결)이 생기지 않게 급수배관을 한다.","src":"기출 2023-64, 2024-62"},{"t":"수조·배관류 자재는 내식성 재료를 쓴다.","src":"기출 2023-64"},{"t":"세면기에는 토수구 공간을 둬 일시적 부압에 의한 역류를 막는다.","src":"기출 2023-64"},{"t":"수조의 급수 유입구와 유출구 사이 거리는 가능한 한 멀게 해 정체 오염을 막는다.","src":"기출 2023-64"},{"t":"건축물 땅밑 저수조는 분뇨·쓰레기 등 유해물질로부터 5 m 이상 띄워 설치한다.","src":"기출 2023-64 | 수도법 시행규칙 별표 3의2"},{"t":"수돗물의 경도는 300 mg/L를 넘지 않아야 한다. 보급수의 경도가 높을수록 보일러 내면에 스케일이 생기기 쉽다.","src":"기출 2021-62, 2021-66"}]},{"머리":"저수조 설치기준","줄":[{"t":"저수조 맨홀 부분은 천장·보 등 건축물로부터 100 cm 이상, 그 밖의 부분은 60 cm 이상 띄운다.","src":"수도법 시행규칙 별표 3의2"},{"t":"물 유출구는 유입구 반대편 밑부분에 설치하되 바닥에서 띄우고, 물칸막이 등으로 물이 고이지 않게 한다.","src":"수도법 시행규칙 별표 3의2"},{"t":"맨홀: 각 변 90 cm 이상 사각형 또는 지름 90 cm 이상 원형을 1개 이상. 5㎥ 이하 소규모 저수조는 60 cm 이상.","src":"수도법 시행규칙 별표 3의2"},{"t":"침전찌꺼기 배출구를 맨 밑에 두고 바닥은 배출구 쪽으로 1/100 이상 경사를 둔다.","src":"수도법 시행규칙 별표 3의2"},{"t":"5㎥를 초과하는 저수조는 둘 이상으로 구획하거나 2개 이상 설치한다.","src":"수도법 시행규칙 별표 3의2"},{"t":"넘치거나 줄어들 때 울리는 경보장치를 설치하고 수신기는 관리실에 둔다.","src":"수도법 시행규칙 별표 3의2"},{"t":"저수조 내부 높이는 최소 1.8 m 이상(옥상 저수조 제외).","src":"수도법 시행규칙 별표 3의2"},{"t":"통기관과 월류관에는 녹슬지 않는 재질의 세목 스크린을 설치한다. 유입배관에는 배수용 밸브를 설치한다.","src":"수도법 시행규칙 별표 3의2"},{"t":"소화용수가 저수조로 역류하지 않게 역류방지장치를 설치한다.","src":"수도법 시행규칙 별표 3의2"}]},{"머리":"절수설비","줄":[{"t":"수도꼭지: 공급수압 98 kPa에서 최대토수유량 1분당 6 L 이하. 공중용 화장실 수도꼭지는 5 L 이하.","src":"기출 2023-72, 2024-61"},{"t":"샤워용 수도꼭지는 샤워호스를 붙인 상태에서 최대토수유량 1분당 7.5 L 이하.","src":"기출 2023-72, 2024-61"},{"t":"소변기는 물을 쓰지 않는 것이거나 사용수량이 2 L 이하.","src":"기출 2024-61"},{"t":"대변기는 사용수량이 6 L 이하. 대·소변 구분형 대변기는 평균사용수량이 6 L 이하.","src":"기출 2024-61 | 보충"}]},{"머리":"급수관 상태검사","줄":[{"t":"최초 일반검사: 준공검사(급수관 갱생·교체 포함)를 한 날부터 5년이 지난 날을 기준으로 6개월 이내에 실시한다.","src":"기출 2025-62"},{"t":"2회 이후 일반검사: 최근 일반검사를 받은 날부터 2년이 되는 날까지 매 2년마다 실시한다.","src":"기출 2025-62"},{"t":"일반검사 급수관 수질기준: 탁도 1NTU 이하, pH 5.8 이상 8.5 이하, 색도 5도 이하, 철 0.3 mg/L 이하, 납 0.01 mg/L 이하, 구리 1 mg/L 이하, 아연 3 mg/L 이하.","src":"수도법 시행규칙 별표 7"},{"t":"전문검사: 수압 측정, 내시경 관찰, 초음파 두께 측정, 유속, 유량, 외부 부식 관찰.","src":"수도법 시행규칙 별표 7"}]},{"머리":"주택 급수 법령","줄":[{"t":"급수·배수용 배관은 콘크리트구조체 안에 매설하지 않는다. 예외: 바닥·벽을 직각으로 관통하는 경우, 구조체 안에 덧관을 미리 매설해 배관하는 경우, 사업계획승인권자가 부득이하다고 인정해 부식 방지·수선 교체를 쉽게 한 경우.","src":"주택건설기준 등에 관한 규정 제43조제1항"},{"t":"화장실 급수용 배관에는 감압밸브 등 수압조절장치를 설치해 세대별 수압을 일정하게 유지한다.","src":"주택건설기준 등에 관한 규정 제43조제2항"},{"t":"층하배관공법으로 배수용 배관을 설치할 때는 일반용 경질 염화비닐관보다 5 dB 이상 소음 차단성능이 있는 저소음형 배관을 쓴다.","src":"주택건설기준 등에 관한 규정 제43조제2항"},{"t":"공동주택에는 세대별 수도계량기와 세대마다 2개소 이상의 급수전을 설치한다.","src":"주택건설기준 등에 관한 규정 제43조제3항"},{"t":"부엌·욕실·화장실·다용도실과 발코니 바닥에는 배수설비를 하고, 악취와 배수 역류를 막는 시설을 한다. 급수설비가 없는 발코니는 예외.","src":"주택건설기준 등에 관한 규정 제43조제4·5항"},{"t":"먹는물 급수조·저수조는 수질을 오염시키지 않는 재료로 하고, 청소가 쉬우며 먹는물 외의 물질이 들어갈 수 없는 구조로 한다.","src":"주택건설기준 등에 관한 규정 제43조제6항"},{"t":"먹는물용 배관설비는 다른 용도의 배관설비와 직접 연결하지 않는다.","src":"건축물의 설비기준 등에 관한 규칙 제18조"},{"t":"주거용 건축물 급수관 지름 최소기준: 1세대 15 mm, 2·3세대 20 mm, 4·5세대 25 mm, 6~8세대 32 mm, 9~16세대 40 mm, 17세대 이상 50 mm.","src":"건축물의 설비기준 등에 관한 규칙 별표 3"},{"t":"비상급수시설: 지하양수시설은 1일 세대당 0.2톤(시·군 0.1톤) 이상 양수, 비상전원 연결 펌프, 세대당 0.3톤 이상 저수하는 지하저수조를 함께 설치한다.","src":"주택건설기준 등에 관한 규정 제35조"},{"t":"비상급수 지하저수조: 고가수조 저수량(세대당 0.25톤까지 산입)을 포함해 세대당 0.5톤(독신자용 0.25톤) 이상 저수하고, 50세대(독신자용 100세대)당 수동식펌프 1대 이상 또는 비상전원 연결 펌프를 설치한다.","src":"주택건설기준 등에 관한 규정 제35조"}]}],"함정":[{"x":"펌프의 공동현상(cavitation)을 방지하기 위하여 펌프의 설치 위치를 수조의 수위보다 높게 하는 것이 바람직하다.","o":"수조 수위보다 낮게 한다.","src":"기출 2021-62"},{"x":"급수펌프의 회전수를 2배로 하면 양정은 8배가 된다.","o":"양정은 4배, 축동력이 8배다.","src":"기출 2021-66"},{"x":"펌프의 흡입양정이 작을수록 서징현상 방지에 유리하다.","o":"흡입양정이 작을수록 공동현상 방지에 유리하다.","src":"기출 2021-66"},{"x":"펌프직송방식은 정전이 될 경우 비상발전기가 없어도 일정량의 급수가 가능하다.","o":"비상발전기가 없으면 급수가 안 된다.","src":"기출 2021-66"},{"x":"고층건물의 급수 조닝방법으로 안전밸브를 설치하는 것이 있다.","o":"감압밸브 방식이 있다.","src":"기출 2021-66"},{"x":"게이트 밸브는 주로 유량조절에 사용하며 글로브 밸브에 비해 유체에 대한 저항이 큰 단점을 갖고 있다.","o":"게이트 밸브는 글로브 밸브보다 저항이 작다.","src":"기출 2022-78"},{"x":"펌프의 성능곡선은 양수량, 관경, 유속, 비체적 등의 관계를 나타낸 것이다.","o":"양수량에 대한 양정·효율·축동력의 관계를 나타낸다.","src":"기출 2022-77"},{"x":"고가수조방식은 건물 내 모든 층의 위생기구에서 압력이 동일하다.","o":"층마다 압력이 다르다.","src":"기출 2023-61"},{"x":"흡입양정을 크게 할수록 공동현상(cavitation) 방지에 유리하다.","o":"흡입양정을 낮출수록 유리하다.","src":"기출 2023-62"},{"x":"펌프의 실양정은 흡입양정, 토출양정, 배관 손실수두의 합이다.","o":"실양정은 흡입양정과 토출양정의 합이다. 손실수두는 전양정에 더한다.","src":"기출 2023-62"},{"x":"펌프의 전양정은 펌프의 회전수에 반비례한다.","o":"회전수의 제곱에 비례한다.","src":"기출 2023-62"},{"x":"펌프의 회전수를 2배로 하면 펌프의 축동력은 4배가 된다.","o":"축동력은 8배다.","src":"기출 2023-62"},{"x":"수조의 급수 유입구와 유출구 사이의 거리는 가능한 한 짧게 하여 정체에 의한 오염이 발생하지 않도록 한다.","o":"가능한 한 멀게 한다.","src":"기출 2023-64"},{"x":"공중용 화장실에 설치하는 수도꼭지는 최대토수유량이 1분당 6리터 이하인 것","o":"공중용 화장실 수도꼭지는 5 L 이하다.","src":"기출 2024-61"},{"x":"대변기는 사용수량이 9리터 이하인 것","o":"6 L 이하다.","src":"기출 2024-61"},{"x":"샤워용 수도꼭지는 해당 수도꼭지에 샤워호스(hose)를 부착한 상태로 측정한 최대토수유량이 1분당 9리터 이하인 것","o":"7.5 L 이하다.","src":"기출 2024-61"},{"x":"대ㆍ소변 구분형 대변기는 평균사용수량이 9리터 이하인 것","o":"6 L 이하다.","src":"기출 2024-61"},{"x":"고가수조방식은 타 급수방식에 비해 수질오염 가능성이 낮다.","o":"가능성이 높다.","src":"기출 2024-62"},{"x":"수도직결방식은 건물 내 정전 시 급수가 불가능하다.","o":"정전과 무관하게 급수된다.","src":"기출 2024-62"},{"x":"배관의 크로스커넥션을 통해 수질오염을 방지한다.","o":"크로스 커넥션은 오염 원인이다. 생기지 않게 해야 한다.","src":"기출 2024-62"},{"x":"동시사용률은 위생기기의 개수가 증가할수록 커진다.","o":"작아진다.","src":"기출 2024-62"},{"x":"양정은 10 % 증가하고, 축동력은 21 % 증가한다.","o":"회전수 10% 증가: 양정 21%, 축동력 약 33% 증가.","src":"기출 2024-64"},{"x":"양정은 21 % 증가하고, 축동력은 10 % 증가한다.","o":"양정 21%, 축동력 약 33%.","src":"기출 2024-64"},{"x":"양정은 약 33 % 증가하고, 축동력은 10 % 증가한다.","o":"양정 21%, 축동력 약 33%.","src":"기출 2024-64"},{"x":"양정은 약 33 % 증가하고, 축동력은 21 % 증가한다.","o":"양정 21%, 축동력 약 33%.","src":"기출 2024-64"}]},"급탕설비":{"묶음":[{"머리":"급탕방식","줄":[{"t":"급탕방식: 중앙식(직접가열식·간접가열식)과 개별식(국소식, 필요한 개소마다 가열기 설치).","src":"기출 2022-64"},{"t":"직접가열식: 열효율이 높고 소규모에 적합하지만 고층에서는 고압에 견디는 보일러가 필요하고 수처리를 많이 해야 한다.","src":"기출 2021-64, 2024-72"},{"t":"간접가열식: 저탕조 안에 가열코일을 두고 증기 등으로 물을 가열한다. 저압 보일러를 쓸 수 있고 대형 건물에 적합하다.","src":"기출 2021-64, 2024-72, 2025-66"},{"t":"중앙식은 개별식보다 배관 열손실이 크다. 온수를 빨리 얻으려면 복관식(순환식)으로 한다.","src":"기출 2024-72 | 보충"},{"t":"기수혼합식 탕비기는 증기를 물에 직접 불어넣어 열효율이 높으나 소음이 크다. 소음을 줄이려고 소음기(사일렌서)를 쓴다.","src":"기출 2022-64, 2025-66 | 보충"},{"t":"순간온수기는 벤튜리의 압력차로 다이어프램을 구동해 작동한다.","src":"기출 2025-66"}]},{"머리":"안전·제어 장치","줄":[{"t":"저탕탱크 온수온도를 설정온도로 유지하려고 서모스탯을 설치한다. 급탕온도를 일정하게 하려고 자동온도조절장치를 설치한다.","src":"기출 2022-64, 2024-65, 2025-66"},{"t":"안전밸브: 저탕조 등 내부압력이 오르면 온수를 배출해 압력을 낮춘다.","src":"기출 2024-65"},{"t":"팽창탱크 용량은 급탕계통 전체 수량에 대한 팽창량을 기준으로 산정한다. 팽창관 도중에는 밸브를 설치하지 않는다.","src":"기출 2024-65 | 보충"}]},{"머리":"신축 흡수","줄":[{"t":"배관 신축 흡수 이음: 스위블 조인트(엘보 이용), 신축곡관, 슬리브형, 벨로즈형. 컨트롤 조인트는 신축이음이 아니다.","src":"기출 2022-64, 2023-66, 2024-65, 2025-66"},{"t":"배관이 벽이나 바닥을 관통할 때는 슬리브를 쓴다.","src":"기출 2024-72"}]}],"함정":[{"x":"기수혼합식 탕비기는 소음이 발생하지 않는 장점이 있으나 열효율이 좋지 않다.","o":"소음이 크고 열효율은 높다.","src":"기출 2022-64"},{"x":"팽창관 도중에는 배관의 손상을 방지하기 위해 감압밸브를 설치한다.","o":"팽창관 도중에는 밸브를 설치하지 않는다.","src":"기출 2024-65"},{"x":"중앙식에서 온수를 빨리 얻기 위해 단관식을 적용한다.","o":"복관식(순환식)을 적용한다.","src":"기출 2024-72"},{"x":"기수혼합식은 증기에서 발생하는 소음을 줄이기 위해 스트레이너를 사용한다.","o":"소음기(사일렌서)를 쓴다.","src":"기출 2025-66"}]},"배수·통기·위생 및 오수처리설비":{"묶음":[{"머리":"기구배수부하단위","줄":[{"t":"옥내 배수관의 관경은 기구배수부하단위법 등으로 정한다.","src":"기출 2021-68"},{"t":"기구배수부하단위는 각 기구의 최대 배수유량을 세면기 최대 배수유량으로 나눈 값에 동시사용률 등을 고려해 정한다(소변기 기준이 아니다).","src":"기출 2021-68 | 보충"},{"t":"기구배수부하단위가 낮은 순서: 개인용 세면기 < 주택용 욕조 < 공중용 대변기.","src":"기출 2021-69"},{"t":"배수 수평지관 관경은 접속하는 트랩구경과 기구배수관의 관경과 같거나 커야 하고, 배수가 흐르는 방향으로 관경을 줄이지 않는다.","src":"기출 2021-68"},{"t":"배수 수직관은 가장 큰 배수부하를 담당하는 최하층 관경을 최상층까지 동일하게 적용한다.","src":"기출 2021-68"}]},{"머리":"트랩","줄":[{"t":"배수트랩 구비조건: 하수가스·냄새의 역류 방지, 오물이 부착·침전하기 어려울 것(포집기류 제외), 봉수 깊이가 항상 유지되는 구조, 간단한 구조. 자기사이펀 작용이 일어나지 않아야 한다.","src":"기출 2021-70"},{"t":"봉수파괴 원인: 자기사이펀작용, 유인(흡인)사이펀작용, 분출(역압)작용, 모세관현상, 증발작용, 관성. 수격작용은 봉수파괴 원인이 아니다.","src":"기출 2022-61 | 보충"},{"t":"트랩 단면 용어: 웨어(weir), 디프(dip), 벤트(vent). 2025년 기출 그림 문항의 정답은 ㄱ 디프, ㄴ 웨어.","src":"기출 2025-64"}]},{"머리":"통기관","줄":[{"t":"외부에 개방되는 통기관 말단은 인접 건물의 문, 개폐 창문과 인접하지 않게 한다.","src":"기출 2023-73"},{"t":"결합통기관: 배수수직관과 통기수직관을 연결해 배수수직관 내 압력변동을 막는다.","src":"기출 2023-73, 2024-73"},{"t":"통기수직관은 빗물수직관과 연결하지 않는다.","src":"기출 2023-73"},{"t":"각개통기관은 수직올림 위치를 동수구배선보다 위에 두고, 기구의 넘침면보다 15 cm 정도 위에서 통기수평지관과 접속한다.","src":"기출 2023-73"},{"t":"통기관 종류: 각개통기관, 루프(회로)통기관, 도피통기관, 습윤통기관, 신정통기관, 결합통기관, 공용통기관.","src":"기출 2024-73 | 보충"}]},{"머리":"청소구","줄":[{"t":"청소구 설치 장소: 배수수직관의 최하단부, 건물 배수관과 부지 하수관이 접속하는 곳, 배관이 45° 이상 각도로 구부러지는 곳, 수평관 관경 100 mm 초과 시 직선길이 30 m 이내마다.","src":"기출 2024-66"},{"t":"배수 수평지관은 최상단부(상류 끝)에 청소구를 둔다. 최하단부가 아니다.","src":"기출 2024-66 | 보충"},{"t":"수평관 관경 100 mm 이하는 직선길이 15 m 이내마다.","src":"보충"}]},{"머리":"위생기구","줄":[{"t":"세락식 대변기: 오물을 직접 유수부에 낙하시켜 물의 낙차로 배출한다. 세출식은 오물을 얕은 유수부에 받았다가 물로 씻어낸다.","src":"기출 2022-65 | 보충"},{"t":"사이펀제트식 대변기는 분수구에서 높은 압력으로 물을 뿜어 유수를 배수관으로 유인한다.","src":"기출 2022-65 | 보충"},{"t":"위생기구 설비의 유닛화는 공기단축과 시공정밀도 향상 장점이 있다.","src":"기출 2022-65"},{"t":"위생기구는 흡수성이 작고 내식성·내마모성이 우수해야 한다.","src":"기출 2022-65"}]},{"머리":"오수처리","줄":[{"t":"BOD: 오수 중 유기물이 미생물에 의해 분해될 때 소비되는 산소량. BOD 제거율이 높을수록 정화조 성능이 우수하다.","src":"기출 2022-66, 2025-68"},{"t":"COD: 화학적산소요구량. SS: 부유물질. DO: 용존산소량이며 DO 값이 클수록 정화능력이 우수하다.","src":"기출 2022-66, 2025-68 | 보충"},{"t":"오수처리에 쓰는 미생물에는 호기성미생물과 혐기성미생물이 있다.","src":"기출 2022-66"},{"t":"분뇨: 수거식 화장실에서 수거되는 액체성 또는 고체성 오염물질.","src":"기출 2022-66"},{"t":"부패탱크방식 정화조의 처리 순서: 부패조 → 산화조 → 소독조. 산화조는 호기성균을 이용한다.","src":"기출 2024-63, 2025-68"},{"t":"스크린: 오수 여과과정에서 고형물이나 이형물을 제거한다.","src":"기출 2025-68"}]},{"머리":"하수도법 용어","줄":[{"t":"개인하수도: 건물·시설 등의 설치자 또는 소유자가 하수를 유출·처리하려고 설치하는 배수설비·개인하수처리시설과 그 부대시설.","src":"기출 2021-72"},{"t":"합류식하수관로: 오수와 하수도로 유입되는 빗물·지하수가 함께 흐르게 한 하수관로.","src":"기출 2021-72, 2025-68"},{"t":"분류식하수관로: 오수와 빗물·지하수가 각각 구분되어 흐르게 한 하수관로.","src":"기출 2021-72"},{"t":"우수관과 오수관은 분리해 배관한다.","src":"건축물의 설비기준 등에 관한 규칙 제17조"},{"t":"배수용 배관은 배수트랩·통기관을 설치해 위생에 지장이 없게 하고, 지하실 등 자연배수가 안 되는 곳에는 강제배수시설을 설치한다.","src":"건축물의 설비기준 등에 관한 규칙 제17조"},{"t":"콘크리트구조체를 관통하거나 매설하는 배수배관은 덧관을 미리 매설하는 등 부식 방지와 수선·교체가 쉽게 한다.","src":"건축물의 설비기준 등에 관한 규칙 제17조"}]}],"함정":[{"x":"기구배수부하단위는 각 기구의 최대 배수유량을 소변기 최대 배수유량으로 나눈 값에 동시사용률 등을 고려하여 결정한다.","o":"세면기 최대 배수유량을 기준으로 나눈다.","src":"기출 2021-68"},{"x":"자기사이펀 작용이 원활하게 일어나야 한다(배수트랩 구비조건).","o":"자기사이펀 작용이 일어나지 않아야 한다.","src":"기출 2021-70"},{"x":"수격작용은 트랩의 봉수파괴 원인이다.","o":"수격작용은 봉수파괴 원인이 아니다.","src":"기출 2022-61"},{"x":"DO는 용존산소량으로 DO 값이 작을수록 오수의 정화능력이 우수하다.","o":"DO 값이 클수록 우수하다.","src":"기출 2022-66"},{"x":"각개통기관의 수직올림위치는 동수구배선보다 아래에 위치시켜 흐름이 원활하도록 하여야 한다.","o":"동수구배선보다 위에 둔다.","src":"기출 2023-73"},{"x":"배수 수평지관의 최하단부에 청소구를 설치한다.","o":"최상단부에 설치한다.","src":"기출 2024-66"},{"x":"SS는 오수 중의 용존산소량을 나타낸다.","o":"SS는 부유물질이다. 용존산소량은 DO다.","src":"기출 2025-68"}]},"냉난방·환기설비":{"묶음":[{"머리":"보일러 용어","줄":[{"t":"정격출력 = 상용출력 + 예열부하. 상용출력 = 난방부하 + 급탕부하 + 배관부하(손실).","src":"기출 2023-69, 2024-69 | 보충"},{"t":"보일러 1마력: 1시간에 100℃의 물 15.65 kg을 증기로 증발시킬 수 있는 능력.","src":"기출 2023-69"},{"t":"환산증발량: 100℃의 물을 100℃의 증기로 증발시키는 것을 기준으로 환산한 실제증발량.","src":"기출 2024-69 | 보충"},{"t":"이코노마이저: 배열에서 회수한 열로 급수를 예열한다(연소용 공기 예열은 공기예열기).","src":"기출 2023-69, 2024-69"},{"t":"저위발열량은 수증기의 잠열을 제외한 열량이고, 고위발열량은 잠열을 포함한 총발열량이다.","src":"기출 2023-69, 2024-69"},{"t":"수관보일러는 노통연관보일러보다 대규모 시설에 적합하다.","src":"기출 2024-69"}]},{"머리":"열량 계산","줄":[{"t":"가열 열량 Q = 질량 × 비열 × 온도차. 20℃ 물 3,000 kg을 90℃로 올리는 열량은 3,000 × 1 × 70 = 210,000 kcal이며, 필요 가스량은 이를 가스 발열량으로 나눠 구한다(24.50 ㎥).","src":"기출 2021-63"},{"t":"20℃ 물 3 kg을 100℃ 증기로: 현열 3 × 4.2 × 80 = 1,008 kJ + 증발잠열 3 × 2,257 = 6,771 kJ = 7,779 kJ.","src":"기출 2024-71"},{"t":"CO2 농도 기준 필요 환기량 Q = 발생량 ÷ (실내 허용농도 − 외기 농도).","src":"기출 2022-76 | 보충"}]},{"머리":"증기난방과 온수난방","줄":[{"t":"온수난방은 증기난방보다 예열시간이 길고 방열량 조절이 쉽다. 증기난방은 방열기 방열면적이 작아도 되고 부하 변동에 방열량 조절이 어렵다.","src":"기출 2022-69, 2024-68"},{"t":"증기난방은 난방하지 않을 때 배관이 비어 있어 한랭지에서 동결 파손 우려가 적다.","src":"기출 2022-69"},{"t":"온수난방은 역환수방식이 직접환수방식보다 각 방열기에 온수를 균등하게 공급한다.","src":"기출 2024-68"},{"t":"증기난방 기계환수식: 응축수를 응축수 탱크에 모아 펌프로 보일러에 공급한다. 건식환수배관은 환수주관이 보일러 수면보다 위에 있다.","src":"기출 2023-67"},{"t":"증기트랩의 기계식에는 플로트트랩, 버킷트랩이 있다. 증기와 응축수의 온도·엔탈피 차이를 이용하는 것은 온도조절식 트랩이다.","src":"기출 2023-67, 2023-68 | 보충"},{"t":"관경 결정에서 마찰저항에 의한 압력손실은 유체밀도에 비례한다.","src":"기출 2023-67"},{"t":"방열기 밸브·공기빼기 밸브는 증기와 온수 모두에 쓴다. 리턴콕은 온수 유량을 조절한다. 2중 서비스 밸브는 방열기 밸브와 열동트랩을 조합한 구조.","src":"기출 2023-68"}]},{"머리":"복사난방","줄":[{"t":"바닥복사난방은 대류난방보다 실내 상하 온도분포 편차가 작아 쾌적하고, 천장이 높은 대공간과 실이 개방된 상태에서도 난방효과가 있다.","src":"기출 2021-71, 2022-69, 2024-67"},{"t":"배관이 구조체에 매립되어 누설 시 유지보수가 어렵다. 예열시간이 길다.","src":"기출 2021-71, 2022-69, 2024-67"},{"t":"바닥에 방열기를 두지 않아 바닥면적 이용도가 높아진다.","src":"기출 2021-71"},{"t":"동일 방열량이면 바닥복사난방은 실의 평균온도가 낮아 손실열량이 적다. 저온수 복사난방은 일시적 난방에 부적합하다.","src":"기출 2023-67, 2024-67 | 보충"}]},{"머리":"지역난방","줄":[{"t":"열병합발전은 미활용 에너지를 쓸 수 있어 에너지절약 효과가 있다.","src":"기출 2021-67"},{"t":"단지 난방 운용 인원 감소, 기계실 면적 감소, 건물이 밀집할수록 배관 매설비용 감소.","src":"기출 2021-67"},{"t":"건물이 플랜트에서 멀수록 열매 반송 동력이 증가한다.","src":"기출 2021-67"},{"t":"고온수를 열매로 쓰면 공동주택 단지 내 기계실 등에서 열교환한다.","src":"기출 2024-68"}]},{"머리":"온수온돌과 난방 법령","줄":[{"t":"온수온돌은 바탕층, 단열층, 채움층, 배관층(방열관 포함), 마감층으로 구성된다.","src":"기출 2025-73 | 건축물의 설비기준 등에 관한 규칙 별표 1의7"},{"t":"채움층: 온돌구조 높이 조정, 차음성능 향상, 보조적 단열기능을 위해 배관층과 단열층 사이에 완충재 등을 설치하는 층.","src":"기출 2025-73"},{"t":"배관층: 단열층 또는 채움층 위에 방열관을 설치하는 층. 방열관: 열을 발산하는 온수를 순환시키려고 배관층에 설치하는 온수배관.","src":"기출 2025-73"},{"t":"바탕층이 지면에 접하면 바탕층 아래와 주변 벽면에 높이 10 cm 이상 방수처리를 하고, 단열재 윗부분에 방습처리를 한다.","src":"건축물의 설비기준 등에 관한 규칙 별표 1의7"},{"t":"6층 이상 공동주택의 난방설비는 중앙집중난방방식(지역난방 포함)으로 한다.","src":"주택건설기준 등에 관한 규정 제37조제1항"},{"t":"중앙집중난방 난방구획: 4층 이상 10층 이하 건축물은 2개소 이상, 10층 초과 건축물은 10층을 넘는 5개 층마다 1개소를 더한 수 이상.","src":"주택건설기준 등에 관한 규정 제37조제2항"},{"t":"중앙집중난방 공동주택 각 세대에는 난방열량 계량기와 난방온도 조절장치를 설치한다.","src":"주택건설기준 등에 관한 규정 제37조제3항"},{"t":"공동주택 각 세대에는 발코니 등에 냉방설비 배기장치 설치공간을 마련한다(중앙집중냉방 제외).","src":"주택건설기준 등에 관한 규정 제37조제5항"},{"t":"개별난방 보일러는 거실 외의 곳에 설치하고 경계벽은 출입구를 제외하고 내화구조로 구획한다.","src":"건축물의 설비기준 등에 관한 규칙 제13조"},{"t":"보일러실 윗부분에 면적 0.5㎡ 이상 환기창, 윗부분과 아랫부분에 각각 지름 10 cm 이상 공기흡입구·배기구를 항상 열어 둔다. 보일러 연도는 내화구조의 공동연도로 한다.","src":"건축물의 설비기준 등에 관한 규칙 제13조"}]},{"머리":"환기설비 기준","줄":[{"t":"30세대 이상 신축·리모델링 공동주택은 시간당 0.5회 이상 환기되도록 자연환기설비 또는 기계환기설비를 설치한다.","src":"기출 2025-70 | 건축물의 설비기준 등에 관한 규칙 제11조제1항"},{"t":"자연환기설비를 설치하면 지방건축위원회 심의를 받는다. KS F 2921 성능시험을 거쳐 별표 1의3 설치 길이 이상으로 설치하면 제외한다.","src":"건축물의 설비기준 등에 관한 규칙 제11조제2항"},{"t":"기계환기설비는 세대 환기량을 최소·적정·최대 3단계 이상 조절할 수 있어야 하고, 적정 단계는 시간당 0.5회 환기 풍량을 확보한다. 24시간 가동할 수 있어야 한다.","src":"건축물의 설비기준 등에 관한 규칙 별표 1의5"},{"t":"외부에 면하는 공기흡입구와 배기구는 1.5 m 이상 이격하거나, 방향이 서로 90도 이상 되는 위치에 설치한다.","src":"기출 2022-67 | 건축물의 설비기준 등에 관한 규칙 별표 1의5"},{"t":"공기여과기 입자 포집률은 KS B 6141 계수법으로 60% 이상.","src":"건축물의 설비기준 등에 관한 규칙 별표 1의5"},{"t":"기계환기설비 소음: 대표길이 1 m에서 40 dB 이하. 본체가 거주공간 밖에 있으면 대표길이 1 m에서 50 dB 이하이거나 거주공간 중앙 바닥 1.0~1.2 m 높이에서 40 dB 이하.","src":"건축물의 설비기준 등에 관한 규칙 별표 1의5"},{"t":"열회수형 환기장치는 KS B 6879 시험 유효환기량이 표시용량의 90% 이상.","src":"건축물의 설비기준 등에 관한 규칙 별표 1의5"},{"t":"100세대 이상 신축 공동주택 실내공기질 측정항목: 폼알데하이드, 벤젠, 톨루엔, 에틸벤젠, 자일렌, 스티렌, 라돈.","src":"기출 2025-71 | 보충"}]},{"머리":"냉동사이클","줄":[{"t":"압축식 냉동기 사이클 순서: 압축기 → 응축기 → 팽창밸브 → 증발기.","src":"기출 2025-69 | 보충"}]}],"함정":[{"x":"정격출력은 난방부하, 급탕부하, 예열부하의 합이다.","o":"상용출력(난방+급탕+배관부하)에 예열부하를 더한 값이다.","src":"기출 2023-69"},{"x":"저위발열량은 연소직전 상변화에 포함되는 증발잠열을 포함한 열량을 말한다.","o":"저위발열량은 잠열을 제외한다.","src":"기출 2023-69, 2024-69"},{"x":"동일 방열량에 대하여 바닥복사난방은 대류난방보다 실의 평균온도가 높기 때문에 손 실열량이 많다.","o":"평균온도가 낮아 손실열량이 적다.","src":"기출 2023-67"},{"x":"버킷트랩은 증기와 응축수의 온도 및 엔탈피 차이를 이용하여 응축수를 배출하는 방식이다.","o":"버킷트랩은 기계식으로 밀도(부력) 차이를 이용한다.","src":"기출 2023-68"},{"x":"실내의 상하 온도분포 차이가 커서 대류난방 방식보다 쾌적성이 좋지 않다.","o":"복사난방은 상하 온도분포 차이가 작아 쾌적하다.","src":"기출 2021-71"},{"x":"건물이 플랜트로부터 멀리 떨어질수록 열매 반송 동력이 감소한다.","o":"증가한다.","src":"기출 2021-67"},{"x":"온수난방은 증기난방과 비교하여 예열시간이 짧아 간헐운전에 적합하다.","o":"온수난방은 예열시간이 길다.","src":"기출 2022-69"},{"x":"저온수를 이용하는 방식의 복사난방은 일시적인 난방에 효과적이다.","o":"일시적 난방에 부적합하다.","src":"기출 2024-67"},{"x":"온수난방에서 직접환수방식은 역환수방식에 비해 각 방열기에 온수를 균등히 공급할 수 있다.","o":"역환수방식이 더 균등하다.","src":"기출 2024-68"},{"x":"상용출력은 난방부하, 급탕부하 및 축열부하의 합이다.","o":"난방부하, 급탕부하, 배관부하의 합이다.","src":"기출 2024-69"},{"x":"환산증발량은 100℃의 물을 102℃의 증기로 증발시키는 것을 기준으로 하여 보일러의 실제증발량을 환산한 것이다.","o":"100℃ 물을 100℃ 증기로 증발시키는 기준이다.","src":"기출 2024-69"},{"x":"이코노마이저(economizer)는 보일러 배기가스에서 회수한 열로 연소용 공기를 예열하는 장치이다.","o":"배열로 급수를 예열하는 장치다.","src":"기출 2024-69"},{"x":"저위발열량은 연료 연소 시 발생하는 수증기의 잠열을 포함한 것이다.","o":"잠열을 포함하는 것은 고위발열량이다.","src":"기출 2024-69"},{"x":"바탕층이 지면에 접하는 경우에는 바탕층 아래와 주변 벽면에 높이 5센티미터 이상의 방수처리를 하여야 하며, 단열재의 윗부분에 방습처리를 하여야 한다.","o":"높이 10 cm 이상이다.","src":"기출 2025-73"}]},"가스설비":{"묶음":[{"머리":"가스계량기 설치","줄":[{"t":"가스계량기와 화기(그 시설 안에서 사용하는 자체화기 제외) 사이 거리: 2 m 이상.","src":"기출 2022-73 | 도시가스사업법 시행규칙 별표 7"},{"t":"가스계량기와 전기계량기·전기개폐기 사이 거리: 60 cm 이상.","src":"기출 2021-73, 2022-73, 2024-76 | 도시가스사업법 시행규칙 별표 7"},{"t":"가스계량기와 굴뚝(단열조치를 하지 않은 경우)·전기점멸기·전기접속기 사이 거리: 30 cm 이상.","src":"기출 2024-76 | 도시가스사업법 시행규칙 별표 7"},{"t":"가스계량기와 절연조치를 하지 않은 전선 사이 거리: 15 cm 이상.","src":"기출 2021-73, 2022-73, 2024-76 | 도시가스사업법 시행규칙 별표 7"},{"t":"입상관과 화기 사이는 우회거리 2 m 이상, 입상관 밸브는 바닥에서 1.6 m 이상 2 m 이내.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"30㎥/hr 미만 가스계량기는 바닥에서 1.6 m 이상 2 m 이내에 수직·수평으로 설치하고 고정장치로 고정한다. 격납상자, 기계실·보일러실, 문 달린 파이프 덕트 안은 높이 제한이 없다.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"설치 장소: 교체·유지관리가 쉽고, 환기가 양호하며, 직사광선·빗물을 받을 우려가 없는 곳(보호상자 안은 예외). 주택은 가스사용자가 구분 소유·점유하는 건축물의 외벽(실외 검침이 가능하면 예외).","src":"도시가스사업법 시행규칙 별표 7"},{"t":"설치 금지 장소: 공동주택의 대피공간, 방·거실·주방 등 사람이 거처하는 곳, 가스계량기에 나쁜 영향을 줄 우려가 있는 장소.","src":"도시가스사업법 시행규칙 별표 7"}]},{"머리":"가스배관","줄":[{"t":"배관 고정장치 간격: 호칭지름 13 mm 미만 1 m마다, 13 mm 이상 33 mm 미만 2 m마다, 33 mm 이상 3 m마다. 호칭지름 100 mm 이상은 적절한 방법으로 3 m 초과 가능.","src":"기출 2022-73, 2024-76 | 도시가스사업법 시행규칙 별표 7"},{"t":"지하 매설 배관은 지면에서 0.6 m 이상 거리를 유지한다.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"지상배관은 황색. 지하매설배관은 저압 황색, 중압 이상 붉은색.","src":"기출 2024-76 | 도시가스사업법 시행규칙 별표 7"},{"t":"건축물 내·외벽에 노출된 지상배관은 바닥(2층 이상은 각 층 바닥)에서 1 m 높이에 폭 3 cm 황색띠를 2중으로 표시하면 표면색을 황색으로 하지 않아도 된다.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"배관 외부에 사용가스명, 최고사용압력, 가스 흐름방향을 표시한다. 지하 매설배관은 흐름방향 표시를 생략할 수 있다.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"가스용 폴리에틸렌관은 노출배관용으로 쓰지 않는다. 지상배관과 연결하려고 금속관으로 보호하고 지면에서 30 cm 이하로 노출하는 경우는 예외.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"배관은 건축물의 기초 밑에 설치하지 않는다.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"매립 설치된 배관에는 가스 누출을 감지해 자동 차단하는 안전장치나 다기능가스안전계량기를 설치한다.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"가스누출경보차단장치·가스누출자동차단기: 특정가스사용시설, 영업장 면적 100㎡ 이상 식품접객업소, 지하 가스사용시설(가정용 제외)에 설치한다.","src":"도시가스사업법 시행규칙 별표 7"}]},{"머리":"점검 주기","줄":[{"t":"가스사용시설 압력조정기는 매 1년에 1회 이상 안전점검한다. 필터·스트레이너 청소는 설치 후 3년까지 1회 이상, 그 이후 4년에 1회 이상.","src":"기출 2022-73 | 도시가스사업법 시행규칙 별표 7"},{"t":"가스보일러·온수기 설치 시공확인서는 5년간 보존하고 사본을 사용자에게 교부한다.","src":"도시가스사업법 시행규칙 별표 7"}]},{"머리":"정압기","줄":[{"t":"정압기는 도시가스를 안전하고 원활하게 수송하도록 적절한 기밀성능을 가져야 한다.","src":"기출 2025-75 | 도시가스사업법 시행규칙 별표 7"},{"t":"정압기와 필터는 설치 후 3년까지 1회 이상, 그 이후 4년에 1회 이상 분해점검한다.","src":"기출 2025-75 | 도시가스사업법 시행규칙 별표 7"},{"t":"수분 동결로 정압기능을 저해할 우려가 있는 정압기에는 동결방지조치를 한다.","src":"기출 2025-75"},{"t":"정압기 입구와 출구에는 가스차단장치를 설치한다. 정압기 입구에는 수분·불순물 제거장치를 설치한다.","src":"기출 2025-75 | 도시가스사업법 시행규칙 별표 7"},{"t":"도시가스 압력을 측정·기록하는 장치는 정압기 출구에 설치한다.","src":"기출 2025-75 | 도시가스사업법 시행규칙 별표 7"},{"t":"정압기 안전밸브 가스방출관 방출구는 지면에서 5 m 이상(전기시설물 접촉 우려가 있으면 3 m 이상) 높이.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"정압기 출구 배관에는 압력 비정상 상승 시 안전관리자 상주 장소에 통보하는 경보장치를 설치한다.","src":"도시가스사업법 시행규칙 별표 7"}]},{"머리":"가스보일러·주택 가스공급","줄":[{"t":"가스보일러·가스온수기는 전용보일러실에 설치하고 목욕탕이나 환기 안 되는 곳에는 설치하지 않는다. 개방식 가스온수기는 설치할 수 없다.","src":"도시가스사업법 시행규칙 별표 7"},{"t":"배기통 재료는 스테인리스강판이나 배기가스·응축수에 내열·내식성이 있는 것으로 한다. 가스보일러 주변에 일산화탄소 경보기를 설치한다(옥외 설치 등은 예외).","src":"도시가스사업법 시행규칙 별표 7"},{"t":"도시가스 공급이 가능한 지역의 주택은 각 세대까지 가스공급설비를 한다. 500세대 이상 단지는 시·도지사가 가스저장시설을 설치하게 할 수 있다.","src":"주택건설기준 등에 관한 규정 제34조"},{"t":"가스감지기: LNG(공기보다 가벼움)는 천장 쪽, LPG(공기보다 무거움)는 바닥 쪽에 설치한다.","src":"기출 2021-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제10조"}]}],"함정":[{"x":"가스계량기는 절연조치를 하지 않은 전선과는 10 cm 이상 거리를 유지한다.","o":"15 cm 이상이다.","src":"기출 2022-73, 2024-76"},{"x":"가스사용시설에 설치된 압력조정기는 매 2년에 1회 이상 압력조정기의 유지ㆍ관리에 적합한 방법으로 안전점검을 실시한다.","o":"매 1년에 1회 이상이다.","src":"기출 2022-73"},{"x":"가스배관은 움직이지 않도록 고정 부착하는 조치를 하되 그 호칭지름이 13 mm 미만의 것에는 2 m 마다 고정 장치를 설치한다.","o":"13 mm 미만은 1 m마다, 13 mm 이상 33 mm 미만은 2 m마다다.","src":"기출 2022-73, 2024-76"},{"x":"가스계량기와 전기계량기 및 전기개폐기와의 거리는 30 cm 이상 유지한다.","o":"60 cm 이상이다.","src":"기출 2022-73"},{"x":"가스계량기와 전기개폐기 및 전기점멸기와의 거리는 30 cm 이상의 거리를 유지하여야 한다.","o":"전기개폐기는 60 cm 이상, 전기점멸기는 30 cm 이상이다.","src":"기출 2024-76"},{"x":"가스계량기와 화기(그 시설 안에서 사용하는 자체화기는 제외한다) 사이에 유지하여야 하는 거리는 1.5 m 이상으로 하여야 한다.","o":"2 m 이상이다.","src":"기출 2024-76"},{"x":"도시가스의 안정공급을 위하여 정압기의 입구에는 도시가스의 압력을 측정ㆍ기록할 수 있는 장치를 설치해야 한다.","o":"정압기의 출구에 설치한다.","src":"기출 2025-75"}]},"지능형 홈네트워크설비":{"묶음":[{"머리":"구성","줄":[{"t":"홈네트워크 설비는 홈네트워크망, 홈네트워크장비, 홈네트워크사용기기로 구분한다.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제3조"},{"t":"홈네트워크망: 단지망(집중구내통신실에서 세대까지)과 세대망(전유부분 각 세대 안).","src":"지능형 홈네트워크 설비 설치 및 기술기준 제3조"},{"t":"홈네트워크장비: 홈게이트웨이, 세대단말기, 단지네트워크장비, 단지서버.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제3조"},{"t":"홈네트워크사용기기: 원격제어기기, 원격검침시스템, 감지기, 전자출입시스템, 차량출입시스템, 무인택배시스템, 영상정보처리기기·전자경비시스템 등. 세대단말기·홈게이트웨이는 사용기기가 아니라 장비다.","src":"기출 2021-75, 2023-75 | 지능형 홈네트워크 설비 설치 및 기술기준 제3조"},{"t":"공동주택이 홈네트워크망(단지망·세대망)과 홈게이트웨이·세대단말기·단지네트워크장비·단지서버를 모두 갖추면 홈네트워크 설비를 갖춘 것으로 본다. 필수설비는 정전 시 예비전원이 공급되어야 한다(이동형 세대단말기 제외).","src":"지능형 홈네트워크 설비 설치 및 기술기준 제4조"},{"t":"원격검침시스템의 검침정보: 전력, 가스, 난방, 온수, 수도. 출입은 해당하지 않는다.","src":"기출 2024-75 | 지능형 홈네트워크 설비 설치 및 기술기준 제3조"}]},{"머리":"설치공간","줄":[{"t":"통신배관실(TPS실): 통신용 파이프 샤프트 및 통신단자함을 설치하기 위한 공간.","src":"기출 2022-68 | 지능형 홈네트워크 설비 설치 및 기술기준 제3조"},{"t":"집중구내통신실(MDF실): 국선·국선단자함 또는 국선배선반과 초고속통신망장비, 이동통신망장비 등 구내통신선로설비를 설치하는 공간.","src":"기출 2022-68 | 지능형 홈네트워크 설비 설치 및 기술기준 제3조"},{"t":"통신배관실 출입문: 폭 0.7 m, 높이 1.8 m 이상(문틀 내측치수). 잠금장치를 설치하고 관계자 외 출입통제 표시를 붙인다.","src":"기출 2021-74, 2022-68, 2025-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제11조"},{"t":"통신배관실에는 50 mm 이상의 문턱을 설치한다. 차수판 또는 차수막을 설치하면 문턱은 설치하지 않아도 된다.","src":"기출 2021-74, 2022-68, 2023-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제11조"},{"t":"통신배관실의 트레이·배관·덕트 설치용 개구부는 화재 시 층간 확대를 막도록 방화처리제를 사용한다.","src":"기출 2022-68 | 지능형 홈네트워크 설비 설치 및 기술기준 제11조"},{"t":"집중구내통신실은 독립적인 출입구와 잠금장치를 두고, 냉방시설 또는 흡배기용 환풍기를 설치한다. 단지네트워크장비·단지서버를 수용하면 설치 면적을 추가로 확보한다.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제11조"},{"t":"세대단자함은 500 mm × 400 mm × 80 mm(깊이)로 설치할 것을 권장한다.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제11조"}]},{"머리":"장비 설치","줄":[{"t":"단지네트워크장비는 집중구내통신실 또는 통신배관실에 설치하고, 별도 함체나 랙에 넣어 잠금장치를 한다.","src":"기출 2021-74, 2023-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제8조"},{"t":"단지서버는 집중구내통신실 또는 방재실에 설치할 수 있고, 상온·상습인 곳에 설치하며 잠금장치를 한다.","src":"기출 2025-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제9조"},{"t":"홈게이트웨이는 세대단자함에 설치하거나 세대단말기에 포함해 설치할 수 있다.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제6조"},{"t":"홈네트워크 설비는 타 설비와 간섭이 없고 유지보수가 쉽게 설치한다.","src":"기출 2025-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제12조"},{"t":"홈네트워크사용기기의 예비부품은 5% 이상 5년간 확보할 것을 권장한다(내구연한 고려).","src":"기출 2023-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제14조"}]},{"머리":"사용기기 설치기준","줄":[{"t":"가스감지기: LNG는 천장 쪽, LPG는 바닥 쪽. 동체감지기는 유효감지반경을 고려한다. 감지기 상황정보는 단지서버에 전송한다.","src":"기출 2021-74, 2022-68, 2025-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제10조"},{"t":"전자출입시스템: 지상 주동 현관과 지하주차장-주동 연결 출입구에 설치. 화재 등 비상시 소방시스템과 연동해 출입문을 수동으로 여닫게 한다. 강우를 고려하고 접지단자는 프레임 내부에 설치한다.","src":"기출 2023-74, 2025-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제10조"},{"t":"무인택배함 설치수량: 소형주택 세대수의 약 10~15%, 중형주택 이상 세대수의 15~20% 정도 설치할 것을 권장한다.","src":"기출 2021-74, 2023-74 | 지능형 홈네트워크 설비 설치 및 기술기준 제10조"},{"t":"무인택배시스템은 문자서비스(SMS) 또는 세대단말기 알림서비스를 제공하는 제어부와 무인택배함으로 구성한다.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제10조"},{"t":"원격제어기기는 이상상황에 대비해 수동 조작이 가능해야 한다. 원격검침시스템은 정전 등으로 운용시스템이 동작하지 않아도 계량이 가능하고 데이터 값을 보존해야 한다.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제10조"},{"t":"차량출입시스템은 단지 주출입구에 설치하고, 관리자와 통화할 수 있는 영상정보처리기기와 인터폰 등을 설치한다.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제10조"}]},{"머리":"보안","줄":[{"t":"단지서버와 세대별 홈게이트웨이 사이 망은 물리적 방법으로 분리하거나 가상사설통신망·가상근거리통신망·암호화 등 논리적 방법으로 분리한다.","src":"지능형 홈네트워크 설비 설치 및 기술기준 제14조의2"},{"t":"홈네트워크장비 보안요구사항: 데이터 기밀성, 데이터 무결성, 인증, 접근통제, 전송데이터 보안.","src":"지능형 홈네트워크 설비 설치 및 기술기준 별표 1"}]}],"함정":[{"x":"차수판 또는 차수막을 설치하지 않은 통신배관실에는 최소 40 mm 이상의 문턱을 설치하여야 한다.","o":"50 mm 이상이다.","src":"기출 2021-74"},{"x":"가스감지기는 LNG인 경우에는 바닥 쪽에, LPG인 경우에는 천장 쪽에 설치하여야 한다.","o":"LNG는 천장 쪽, LPG는 바닥 쪽이다.","src":"기출 2022-68, 2025-74"},{"x":"차수판 또는 차수막을 설치하지 않은 통신배관실에는 최소 30 mm 이상의 문턱을 설치하여야 한다.","o":"50 mm 이상이다.","src":"기출 2022-68, 2023-74"},{"x":"통신배관실의 출입문은 폭 0.6미터, 높이 1.8미터 이상이어야 한다.","o":"폭 0.7 m, 높이 1.8 m 이상이다.","src":"기출 2022-68"},{"x":"집중구내통신실은 TPS실이라고 하며, 통신용 파이프 샤프트 및 통신단자함을 설치하기 위한 공간을 말한다.","o":"TPS실은 통신배관실이다. 집중구내통신실은 MDF실이다.","src":"기출 2022-68"},{"x":"무인택배함의 설치수량은 소형주택의 경우 세대수의 약 15 ∼ 20 % 정도 설치할 것을 권장한다.","o":"소형주택은 약 10~15%, 중형주택 이상은 15~20%다.","src":"기출 2023-74"},{"x":"홈네트워크 사용기기의 예비부품은 내구연한을 고려하고, 3 % 이상 5년간 확보할 것을 권장한다.","o":"5% 이상 5년간이다.","src":"기출 2023-74"},{"x":"전자출입시스템의 접지단자는 프레임 외부에 설치하여야 한다.","o":"프레임 내부에 설치한다.","src":"기출 2023-74"}]},"전기·조명설비":{"묶음":[{"머리":"배선공사","줄":[{"t":"금속관 공사는 철근콘크리트 구조의 매립공사에 쓴다.","src":"기출 2021-76"},{"t":"합성수지관 공사는 옥내의 점검할 수 없는 은폐장소에도 쓸 수 있다.","src":"기출 2021-76"},{"t":"버스 덕트 공사는 공장·빌딩 등에서 비교적 큰 전류가 흐르는 간선에 쓴다.","src":"기출 2021-76"},{"t":"라이팅 덕트 공사는 화랑의 벽면조명처럼 광원을 이동시킬 필요가 있는 곳에 쓴다.","src":"기출 2021-76"},{"t":"금속 몰드 공사는 옥내 노출 배선에 쓰며, 매립공사나 기계실 전동기 배선용이 아니다.","src":"기출 2021-76 | 보충"}]},{"머리":"세대 전기 설비","줄":[{"t":"세대별 전기시설 용량은 3 kW 이상이다. 전용면적 60㎡ 이상이면 3 kW에 60㎡를 초과하는 10㎡마다 0.5 kW를 더한 값 이상.","src":"기출 2023-77 | 주택건설기준 등에 관한 규정 제40조제1항"},{"t":"전력량계는 세대 전용부분 밖의 검침이 쉬운 곳에 설치한다. 원격검침방식이면 전용부분 안에 설치할 수 있다.","src":"주택건설기준 등에 관한 규정 제40조제2항"},{"t":"주택단지 안 옥외 전선은 지하에 매설한다. 전용면적 60㎡ 이하 주택이 전체 세대수의 1/2 이상인 단지에서 폭 8 m 이상 도로에 가설하는 전선은 가공선으로 할 수 있다.","src":"주택건설기준 등에 관한 규정 제40조제3항"},{"t":"보안등: 어린이놀이터와 도로(폭 15 m 이상이면 양측)에 설치하고 도로의 보안등 간격은 50 m 이내. 외부 밝기에 따라 자동 점멸하거나 시간을 조절하는 장치를 붙인다.","src":"주택건설기준 등에 관한 규정 제33조"},{"t":"전압 구분: 저압은 직류 1.5 kV 이하·교류 1 kV 이하. 고압은 직류 1.5 kV 초과·교류 1 kV 초과이고 7 kV 이하. 특고압은 7 kV 초과.","src":"기출 2025-78 | 보충"}]},{"머리":"수용률·부등률·부하율","줄":[{"t":"수용률 = 최대 수용전력 ÷ 부하설비 용량 합계 × 100(%).","src":"기출 2023-77, 2025-79"},{"t":"부등률 = 개별 최대수요전력의 합 ÷ 합성 최대수요전력. 부하 종별 최대수요전력이 생기는 시간차에서 비롯된다.","src":"기출 2023-77 | 보충"},{"t":"부하율 = 평균 수요전력 ÷ 최대 수요전력 × 100(%). 부하율이 클수록 전기설비가 효율적으로 쓰인다.","src":"기출 2023-77, 2025-79 | 보충"},{"t":"역률개선용 콘덴서: 역률을 개선하려고 변압기·전동기 등에 병렬로 설치하는 커패시터.","src":"기출 2023-77"},{"t":"최대수요전력: 수용가에서 일정 기간 중 사용한 전력의 최대치.","src":"기출 2025-79"},{"t":"가변속제어기(인버터): 정지형 전력변환기로 전동기의 가변속운전을 위해 설치하는 설비. 변압기 대수제어: 부하상태에 따라 운전 대수를 자동 또는 수동으로 제어.","src":"기출 2025-79"},{"t":"일괄소등스위치: 층 또는 구역(세대) 단위로 설치되어 조명등(센서등·비상등 제외 가능)을 한꺼번에 끄는 스위치.","src":"기출 2025-79"}]},{"머리":"조명 용어","줄":[{"t":"광속(lm): 광원에서 발산하는 빛의 양. 광도(cd): 광원에서 어느 방향으로 나가는 빛의 세기. 조도(lx): 면에 도달하는 빛의 밀도. 휘도(cd/㎡).","src":"기출 2024-80 | 보충"},{"t":"연색성: 물체색이 태양광 아래에서 보이는 색과 같으면 연색지수 Ra 100. 연색성이 높을수록 태양광에 가까운 분광분포를 갖는다.","src":"기출 2024-80, 2025-76 | 보충"},{"t":"암순응: 밝은 곳에서 어두운 곳으로 들어갈 때 동공이 확대되어 감광도가 높아지는 현상.","src":"기출 2024-80"},{"t":"메탈할라이드등은 수은등보다 효율과 연색성이 좋다.","src":"기출 2024-80 | 보충"},{"t":"코브조명은 천장을 비춰 반사시키는 간접조명 방식이다.","src":"기출 2024-80 | 보충"},{"t":"색온도: 광원이 발하는 빛의 색을 온도로 나타낸 것. 파란색이 빨간색보다 색온도가 높다.","src":"기출 2025-76"},{"t":"조명률 = 작업면에 도달하는 광속 ÷ 광원의 총광속.","src":"기출 2025-76 | 보충"},{"t":"눈부심(glare): 높은 휘도의 광원 때문에 시각적 불쾌감 등이 생기는 현상.","src":"기출 2025-76"},{"t":"상시인공보조조명(PSALI): 낮에 실내 깊은 곳의 자연채광 부족을 인공조명으로 보충하는 방식.","src":"기출 2025-76 | 보충"}]},{"머리":"조명 계산","줄":[{"t":"광속법: F × N × U × M = E × A (F 개당 광속, N 개수, U 조명률, M 보수율, E 조도, A 바닥면적).","src":"기출 2022-72, 2023-79 | 보충"},{"t":"바닥면적 120㎡, 400 lx, 4,000 lm, 조명률 0.6, 보수율 0.8: N = 400×120÷(4,000×0.6×0.8) = 25개.","src":"기출 2022-72"},{"t":"바닥면적 100㎡, 480 lx, 4,000 lm, 보수율 0.8: 조명률 0.5일 때 30개, 0.6일 때 25개 → 5개 감소.","src":"기출 2023-79"}]}],"함정":[{"x":"금속 몰드 공사는 매립공사용으로 적합하고, 기계실 등에서 전동기로 배선하는 경우에 사용된다.","o":"금속 몰드는 옥내 노출 배선에 쓴다.","src":"기출 2021-76"},{"x":"부하율이 작을수록 전기설비가 효율적으로 사용되고 있음을 나타낸다.","o":"부하율이 클수록 효율적이다.","src":"기출 2023-77"},{"x":"광도는 광원에서 발산하는 빛의 양을 의미하며, 단위는 루멘(lm)을 사용한다.","o":"빛의 양은 광속(lm)이다. 광도의 단위는 칸델라(cd)다.","src":"기출 2024-80"},{"x":"어떤 물체의 색깔이 태양광 아래에서 보이는 색과 동일한 색으로 인식될 경우, 그 광원의 연색지수를 Ra 50으로 한다.","o":"Ra 100이다.","src":"기출 2024-80"},{"x":"수은등은 메탈할라이드등보다 효율과 연색성이 좋다.","o":"메탈할라이드등이 더 좋다.","src":"기출 2024-80"},{"x":"코브조명은 천장을 비추어 현휘를 방지할 수 있는 직접조명 방식이다.","o":"간접조명 방식이다.","src":"기출 2024-80"},{"x":"상시인공보조조명(PSALI)은 전반조명과 국부조명을 조합하여 조명 효율성을 높인 방식이다.","o":"PSALI는 주간 자연채광 부족을 인공조명으로 보충하는 방식이다.","src":"기출 2025-76"},{"x":"광원이 발광하는 빛의 색을 온도로 나타낸 것이 색온도이며, 빨간색은 파란색에 비해 색온도가 높다.","o":"파란색이 더 높다.","src":"기출 2025-76"},{"x":"광원의 연색성이 낮을수록 태양광선에 더욱 가까운 분광분포를 갖는다.","o":"연색성이 높을수록 가깝다.","src":"기출 2025-76"},{"x":"조명률은 광원의 총광속을 조명 작업면에 도달하는 광속으로 나눈 것이다.","o":"작업면에 도달하는 광속을 총광속으로 나눈 것이다.","src":"기출 2025-76"},{"x":"“부하율”이라 함은 부하설비 용량 합계에 대한 최대 수용전력의 백분율을 말한다.","o":"그 설명은 수용률이다.","src":"기출 2025-79"}]},"소방설비":{"묶음":[{"머리":"소방시설의 종류(소방시설법 시행령 별표 1)","줄":[{"t":"소화설비: 소화기구(소화기, 간이소화용구, 자동확산소화기), 자동소화장치(주거용 주방자동소화장치, 상업용 주방자동소화장치, 캐비닛형, 가스, 분말, 고체에어로졸 자동소화장치), 옥내소화전설비(호스릴 포함), 스프링클러설비등(스프링클러, 간이스프링클러, 화재조기진압용), 물분무등소화설비, 옥외소화전설비.","src":"소방시설 설치 및 관리에 관한 법률 시행령 별표 1"},{"t":"물분무등소화설비: 물분무, 미분무, 포, 이산화탄소, 할론, 할로겐화합물 및 불활성기체, 분말, 강화액, 고체에어로졸 소화설비.","src":"소방시설 설치 및 관리에 관한 법률 시행령 별표 1"},{"t":"경보설비: 단독경보형 감지기, 비상경보설비(비상벨설비, 자동식사이렌설비), 자동화재탐지설비, 시각경보기, 화재알림설비, 비상방송설비, 자동화재속보설비, 통합감시시설, 누전경보기, 가스누설경보기.","src":"기출 2023-70 | 소방시설 설치 및 관리에 관한 법률 시행령 별표 1"},{"t":"피난구조설비: 피난기구(피난사다리, 구조대, 완강기, 간이완강기 등), 인명구조기구(방열복·방화복, 공기호흡기, 인공소생기), 유도등(피난유도선, 피난구유도등, 통로유도등, 객석유도등, 유도표지), 비상조명등 및 휴대용비상조명등.","src":"기출 2022-80 | 소방시설 설치 및 관리에 관한 법률 시행령 별표 1"},{"t":"소화용수설비: 상수도소화용수설비, 소화수조·저수조, 그 밖의 소화용수설비.","src":"기출 2023-70 | 소방시설 설치 및 관리에 관한 법률 시행령 별표 1"},{"t":"소화활동설비: 제연설비, 연결송수관설비, 연결살수설비, 비상콘센트설비, 무선통신보조설비, 연소방지설비. 제연설비는 피난구조설비가 아니다.","src":"기출 2022-80, 2023-70 | 소방시설 설치 및 관리에 관한 법률 시행령 별표 1"}]},{"머리":"피난기구 정의","줄":[{"t":"완강기: 사용자의 몸무게에 따라 자동으로 내려올 수 있는 기구 중 사용자가 교대로 연속 사용할 수 있는 것.","src":"기출 2021-80"},{"t":"구조대: 포지 등으로 자루형태를 만들어 사용자가 그 내부에 들어가 내려옴으로써 대피하는 기구.","src":"기출 2021-80"},{"t":"다수인피난장비: 화재 시 2인 이상의 피난자가 동시에 해당층에서 지상 또는 피난층으로 하강하는 피난기구.","src":"기출 2021-80"}]},{"머리":"옥내소화전설비 수원·가압송수","줄":[{"t":"수원 저수량: 설치개수가 가장 많은 층의 설치개수(2개 이상이면 2개) × 2.6㎥(호스릴 포함).","src":"기출 2021-78 | 옥내소화전설비의 화재안전성능기준 제4조"},{"t":"수원은 유효수량 외에 유효수량의 1/3 이상을 옥상에 설치한다. 수조는 소화설비 전용으로 한다.","src":"옥내소화전설비의 화재안전성능기준 제4조"},{"t":"방수압력 0.17 MPa 이상, 방수량 분당 130 L 이상(2개 동시 사용 기준). 노즐 방수압력이 0.7 MPa를 초과하면 호스접결구 인입측에 감압장치를 설치한다.","src":"기출 2022-74 | 옥내소화전설비의 화재안전성능기준 제5조"},{"t":"펌프 토출량 = 설치개수가 가장 많은 층의 설치개수(2개 이상이면 2개) × 분당 130 L 이상.","src":"옥내소화전설비의 화재안전성능기준 제5조"},{"t":"펌프 성능: 체절운전 때 정격토출압력의 140%를 넘지 않고, 정격토출량의 150%로 운전할 때 정격토출압력의 65% 이상.","src":"옥내소화전설비의 화재안전성능기준 제5조"},{"t":"고가수조·압력수조·가압수조의 방수압·방수량은 20분 이상 유지되어야 한다. 내연기관 사용 시 펌프를 20분 이상 운전할 수 있는 연료를 갖춘다.","src":"옥내소화전설비의 화재안전성능기준 제5조"},{"t":"비상전원은 옥내소화전설비를 20분 이상 유효하게 작동할 수 있어야 한다. 설치 대상: 7층 이상이면서 연면적 2,000㎡ 이상, 또는 지하층 바닥면적 합계 3,000㎡ 이상.","src":"옥내소화전설비의 화재안전성능기준 제8조"}]},{"머리":"용어 정의","줄":[{"t":"고가수조: 구조물이나 지형지물에 설치해 자연낙차의 압력으로 급수하는 수조.","src":"기출 2021-78 | 옥내소화전설비의 화재안전성능기준 제3조"},{"t":"압력수조: 소화용수와 공기를 채우고 일정 압력 이상으로 가압해 그 압력으로 급수하는 수조.","src":"기출 2021-78 | 옥내소화전설비의 화재안전성능기준 제3조"},{"t":"충압펌프: 배관 내 압력손실에 따른 주펌프의 빈번한 기동을 막으려고 충압 역할을 하는 펌프.","src":"기출 2023-71 | 옥내소화전설비의 화재안전성능기준 제3조"},{"t":"체절운전: 펌프 성능시험을 위해 펌프 토출측 개폐밸브를 닫은 상태에서 펌프를 운전하는 것.","src":"기출 2023-71 | 옥내소화전설비의 화재안전성능기준 제3조"},{"t":"유수검지장치: 유수현상을 자동적으로 검지해 신호 또는 경보를 발하는 장치. 가지배관: 헤드가 설치되어 있는 배관.","src":"기출 2023-71"},{"t":"건식스프링클러헤드: 물과 오리피스가 분리되어 동파를 방지할 수 있는 헤드.","src":"기출 2023-71"}]},{"머리":"옥내소화전 배관·방수구·함","줄":[{"t":"옥내소화전 배관을 연결송수관설비와 겸용하면 주배관 구경 100 mm 이상, 방수구로 연결되는 배관 구경 65 mm 이상.","src":"기출 2024-77 | 옥내소화전설비의 화재안전성능기준 제6조"},{"t":"배관 내 사용압력 1.2 MPa 미만이면 배관용 탄소강관·구리관(습식)·스테인리스강관·덕타일 주철관, 1.2 MPa 이상이면 압력배관용 탄소강관 등을 쓴다.","src":"옥내소화전설비의 화재안전성능기준 제6조"},{"t":"송수구: 지면에서 0.5 m 이상 1 m 이하 높이, 구경 65 mm 쌍구형 또는 단구형. 송수구-주배관 연결배관에는 개폐밸브를 설치하지 않는다.","src":"기출 2021-78 | 옥내소화전설비의 화재안전성능기준 제6조"},{"t":"방수구: 각 부분에서 방수구까지 수평거리 25 m 이하, 바닥으로부터 높이 1.5 m 이하.","src":"옥내소화전설비의 화재안전성능기준 제7조"},{"t":"호스는 구경 40 mm(호스릴옥내소화전설비는 25 mm) 이상.","src":"기출 2022-74 | 옥내소화전설비의 화재안전성능기준 제7조"},{"t":"함에는 옥내소화전설비 위치표시등과 가압송수장치 기동표시등을 설치한다. 기동표시등은 적색등이다.","src":"기출 2021-78 | 옥내소화전설비의 화재안전성능기준 제7조"},{"t":"감시제어반과 동력제어반으로 구분하고, 동력제어반 앞면은 적색으로 한다. 동력제어반 외함은 두께 1.5 mm 이상 강판.","src":"옥내소화전설비의 화재안전성능기준 제9조"}]},{"머리":"공동주택 화재안전성능기준(NFPC 608)","줄":[{"t":"소화기는 바닥면적 100㎡마다 1단위 이상의 능력단위를 기준으로 설치한다. 아파트등은 각 세대와 공용부(승강장, 복도 등)마다 설치한다.","src":"기출 2024-78 | 공동주택의 화재안전성능기준 제5조"},{"t":"주거용 주방자동소화장치: 아파트등 주방에 열원(가스 또는 전기)의 종류에 맞는 것으로 설치하고 열원을 차단하는 장치를 둔다.","src":"기출 2024-78 | 공동주택의 화재안전성능기준 제5조"},{"t":"옥내소화전설비는 호스릴 방식으로 설치한다.","src":"공동주택의 화재안전성능기준 제6조"},{"t":"폐쇄형스프링클러헤드를 쓰는 아파트등은 기준개수 10개 × 1.6㎥ 이상의 수원. 각 동이 주차장으로 연결된 구조이면 주차장 부분 기준개수는 30개.","src":"기출 2025-72 | 공동주택의 화재안전성능기준 제7조"},{"t":"세대 내 스프링클러헤드는 각 부분에서 헤드까지 수평거리 2.6 m 이하. 거실에는 조기반응형 헤드를 설치한다.","src":"기출 2024-78 | 공동주택의 화재안전성능기준 제7조"},{"t":"하나의 방호구역은 2개 층에 미치지 않게 한다(복층형은 3개 층 이내). 외벽 창문에서 0.6 m 이내에 헤드를 배치한다.","src":"공동주택의 화재안전성능기준 제7조"},{"t":"세대 내 거실(취침용 방·거실)에는 연기감지기를 설치한다.","src":"기출 2024-78 | 공동주택의 화재안전성능기준 제11조"},{"t":"비상방송설비 확성기는 각 세대마다 설치하고, 아파트등 실내 확성기 음성입력은 2 W 이상.","src":"기출 2024-78 | 공동주택의 화재안전성능기준 제12조"},{"t":"피난기구는 아파트등 각 세대마다 설치하고, 의무관리대상 공동주택은 관리주체가 관리하는 구역마다 공기안전매트 1개 이상을 추가한다.","src":"공동주택의 화재안전성능기준 제13조"},{"t":"연결송수관·비상콘센트는 계단 출입구로부터 5 m 이내에 설치하되, 해당 층 각 부분까지 수평거리가 50 m를 넘으면 추가한다.","src":"공동주택의 화재안전성능기준 제17조·제18조"},{"t":"감시제어반 전용실은 피난층 또는 지하 1층에 둔다. 상시 사람이 근무하거나 관리가 쉬운 장소이면 지상 2층 또는 지하 2층에도 둘 수 있다.","src":"공동주택의 화재안전성능기준 제6조"}]}],"함정":[{"x":"옥내소화전 송수구의 설치높이는 바닥으로부터의 높이 1.5 m에 설치하여야 한다.","o":"지면에서 0.5 m 이상 1 m 이하다.","src":"기출 2021-78"},{"x":"고가수조란 소화용수와 공기를 채우고 일정압력 이상으로 가압하여 그 압력으로 급수하는 수조를 말한다.","o":"그 설명은 압력수조다. 고가수조는 자연낙차 압력으로 급수한다.","src":"기출 2021-78"},{"x":"체절운전이란 펌프의 성능시험을 목적으로 펌프 토출측의 개폐밸브를 개방한 상태에서 펌프를 운전하는 것을 말한다.","o":"개폐밸브를 닫은 상태다.","src":"기출 2023-71"},{"x":"아파트등의 세대 내 스프링클러헤드를 설치하는 경우 천장ㆍ반자ㆍ천장과 반자사이ㆍ 덕트ㆍ선반등의 각 부분으로부터 하나의 스프링클러헤드까지의 수평거리는 3.2미터 이하로 해야 한다.","o":"2.6 m 이하다.","src":"기출 2024-78"},{"x":"제연설비는 피난구조설비에 해당한다.","o":"제연설비는 소화활동설비다.","src":"기출 2022-80"}]},"승강기설비":{"묶음":[{"머리":"공동주택 승강기 설치(주택건설기준)","줄":[{"t":"6층 이상 공동주택에는 대당 6인승 이상 승용승강기를 설치한다.","src":"주택건설기준 등에 관한 규정 제15조제1항"},{"t":"10층 이상 공동주택의 승용승강기는 비상용승강기의 구조로 한다.","src":"주택건설기준 등에 관한 규정 제15조제2항"},{"t":"10층 이상 공동주택에는 화물용승강기를 설치한다. 적재하중 0.9톤 이상, 승강기 폭·너비 한 변 1.35 m 이상 다른 한 변 1.6 m 이상.","src":"주택건설기준 등에 관한 규정 제15조제3항"},{"t":"화물용승강기 대수: 계단실형은 계단실마다, 복도형은 100세대까지 1대, 100세대를 넘으면 100세대마다 1대 추가.","src":"주택건설기준 등에 관한 규정 제15조제3항"},{"t":"공동주택 승용승강기 대수: 6층 이상 거실면적 합계 3,000㎡ 이하이면 1대, 3,000㎡ 초과 시 3,000㎡ 초과분 3,000㎡ 이내마다 1대 추가. 8~15인승은 1대, 16인승 이상은 2대로 계산한다.","src":"건축물의 설비기준 등에 관한 규칙 별표 1의2"}]},{"머리":"비상용승강기","줄":[{"t":"비상용승강기의 승강로는 각 층에서 피난층까지 이르는 승강로를 단일구조로 연결해 설치한다. 다른 부분과 내화구조로 구획한다.","src":"기출 2022-70 | 건축물의 설비기준 등에 관한 규칙 제10조"},{"t":"비상용승강기 승강장 바닥면적은 승강기 1대에 대해 6㎡ 이상(옥외 승강장 제외).","src":"건축물의 설비기준 등에 관한 규칙 제10조"},{"t":"승강장 출입구에는 60분+ 방화문 또는 60분 방화문을 설치하고, 마감재료는 불연재료로 한다. 노대·외부로 여는 창문 또는 배연설비를 설치한다.","src":"건축물의 설비기준 등에 관한 규칙 제10조"},{"t":"피난층 승강장 출입구에서 도로 또는 공지까지 거리 30 m 이하. 출입구 부근에 비상용승강기 표지를 한다.","src":"건축물의 설비기준 등에 관한 규칙 제10조"},{"t":"비상용승강기를 설치하지 않을 수 있는 건축물: 높이 31 m를 넘는 각 층을 거실 외 용도로 쓰는 건축물, 31 m 초과 각 층 바닥면적 합계 500㎡ 이하, 31 m 초과 층수 4개 층 이하로 200㎡(불연 마감이면 500㎡) 이내마다 방화구획된 건축물.","src":"건축물의 설비기준 등에 관한 규칙 제9조"}]},{"머리":"피난용승강기","줄":[{"t":"피난용승강기 전용 예비전원은 정전 때 피난용승강기·기계실·승강장·폐쇄회로 텔레비전 등을 작동시킬 수 있어야 한다.","src":"기출 2024-74 | 건축물의 피난·방화구조 등의 기준에 관한 규칙 제30조"},{"t":"예비전원 용량: 초고층 건축물 2시간 이상, 준초고층 건축물 1시간 이상 작동.","src":"기출 2024-74 | 건축물의 피난·방화구조 등의 기준에 관한 규칙 제30조"},{"t":"상용전원과 예비전원의 공급을 자동 또는 수동으로 전환할 수 있어야 하고, 전선관·배선은 내열성 자재를 쓰고 방수조치를 한다.","src":"건축물의 피난·방화구조 등의 기준에 관한 규칙 제30조"},{"t":"승강장은 다른 부분과 내화구조 바닥·벽으로 구획하고, 출입구에 60분+ 방화문 또는 60분 방화문(항상 닫힌 상태 유지), 불연재료 마감, 배연설비 또는 제연설비를 설치한다.","src":"건축물의 피난·방화구조 등의 기준에 관한 규칙 제30조"},{"t":"승강로는 다른 부분과 내화구조로 구획하고 상부에 배연설비 또는 제연설비를 설치한다. 기계실도 내화구조로 구획하고 출입구에 60분+ 또는 60분 방화문을 둔다.","src":"건축물의 피난·방화구조 등의 기준에 관한 규칙 제30조"}]},{"머리":"승강기 구조·안전장치","줄":[{"t":"기어리스 구동기는 전동기의 회전력을 감속하지 않고 직접 권상도르래로 전달하는 구조다.","src":"기출 2022-70"},{"t":"완충기: 스프링 또는 유체 등을 이용해 카, 균형추 또는 평형추의 충격을 흡수하는 장치.","src":"기출 2022-70"},{"t":"승강로·기계실·기계류 공간·풀리실 출입문에 인접한 접근 통로는 50 lx 이상 조도의 영구 설치 전기 조명으로 비춘다.","src":"기출 2022-70"},{"t":"카 부문에 설치하는 안전장치는 비상정지 장치다. 전자제동장치(권상기), 조속기, 리밋 스위치, 종점정지 스위치는 카 부문 안전장치가 아니다.","src":"기출 2023-78 | 보충"},{"t":"승강기의 승강로 안에는 승강기 운행에 필요한 배관설비 외의 배관설비를 설치하지 않는다.","src":"건축물의 설비기준 등에 관한 규칙 제17조"},{"t":"승강기 구조는 승강기 안전관리법이 정하는 바에 따른다.","src":"건축물의 설비기준 등에 관한 규칙 제6조"}]},{"머리":"안전인증 결함 구분","줄":[{"t":"승강장문 및 카문 심사항목 중 경미한 결함에 해당하는 것: 자동 작동 승강장 문의 닫힘. 문턱·가이드·현수장치, 승강장문 및 카문 잠금·비상 잠금해제 확인, 여러 문짝이 기계적으로 연결된 개폐식 승강장문, 카문의 닫힘 확인을 입증하는 전기안전장치는 경미한 결함이 아니다.","src":"기출 2025-80"}]}],"함정":[{"x":"옥내에 설치하는 피난용승강기의 승강장 바닥면적은 승강기 1대당 5 m2 이상으로 해야 한다.","o":"승강장 바닥면적 기준은 승강기 1대당 6㎡ 이상이다(비상용승강기 기준).","src":"기출 2022-70"}]}};
